import { Book } from "@/lib/types";

export const revelation: Book = {
  id: "revelation",
  name: "Offenbarung",
  shortName: "Offb",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Offenbarung Jesu Christi, die Gott ihm gab*, um seinen Knechten* zu zeigen, was bald* geschehen muss*; und indem er <sie> durch seinen Engel sandte*, hat er <sie> seinem Knecht* Johannes kundgetan*,", heading: "Thema des Buches", footnotes: ["℘ 1Tim 6,14.15", "w. Sklaven", "o. in Kürze", "℘ V. 19; Kap. 4,1; 22,6; Dan 2,28.45; Zef 1,14", "℘ Kap. 22,16; Dan 8,16", "o. in Kürze", "℘ 4Mo 24,14; Am 3,7"] },
      { number: 2, text: "der das Wort Gottes und das Zeugnis* Jesu Christi bezeugt hat, alles, was er sah*.", footnotes: ["℘ V. 9; Kap. 6,9; 12,17; 14,12; 19,10; 20,4", "℘ Joh 21,24; 1Jo 1,2"] },
      { number: 3, text: "Glückselig, der liest und die hören die Worte der Weissagung und bewahren, was in ihr geschrieben ist*! Denn die Zeit ist nahe*.", footnotes: ["℘ Kap. 22,7; Lk 11,28", "℘ Kap. 22,10"] },
      { number: 4, text: "Johannes den sieben Gemeinden*, die in Asien* sind: Gnade euch und Friede von dem, der ist und der war* und der kommt*, und von den sieben Geistern, die vor seinem Thron sind*,", heading: "Verfasser, Widmung und Gruß", footnotes: ["o. Versammlungen", "d. i. die röm. Provinz Asien; vgl. auch Anm. zu Apg 16,6", "℘ Kap. 11,17; 16,5", "℘ Kap. 4,8", "℘ Kap. 3,1; 4,5; 5,6"] },
      { number: 5, text: "und von Jesus Christus, <der> der treue Zeuge <ist>*, der Erstgeborene der Toten* und der Fürst der Könige der Erde*! Dem, der uns liebt* und uns von unseren Sünden erlöst* hat durch sein Blut*", footnotes: ["℘ Kap. 3,14; Jes 55,4; Joh 18,37", "℘ Kol 1,18", "℘ Kap. 19,16; Ps 72,11; 89,28", "℘ Joh 13,1", "mit anderen Handschr.: gewaschen", "℘ Kap. 7,14; 22,14"] },
      { number: 6, text: "und uns gemacht hat zu einem Königtum, zu Priestern* seinem Gott und Vater: Ihm sei die Herrlichkeit und die Macht von Ewigkeit zu Ewigkeit*! Amen*.", footnotes: ["℘ Kap. 5,10; 20,6; Jes 61,6; 1Petr 2,5.9", "w. in die Zeitalter der Zeitalter (griech. Äonen); so auch V. 18", "Beteuerungsformel für die Wahrhaftigkeit des Gesagten; in den Evangelien am Anfang feierlicher Erklärungen Jesu mit »Wahrlich!« übersetzt; vgl. Kap. 22,20\n℘ Röm 11,36"] },
      { number: 7, text: "Siehe, er kommt* mit den Wolken*, und jedes Auge wird ihn sehen, auch die, welche ihn durchstochen haben*, und wehklagen werden seinetwegen alle Stämme der Erde*. Ja, Amen.", footnotes: ["℘ Ps 50,3", "℘ Dan 7,13; Mt 26,64; Apg 1,11", "℘ Joh 19,37", "o. des Landes\n℘ Mt 24,30"] },
      { number: 8, text: "Ich bin das Alpha und das Omega*, spricht der Herr, Gott, der ist und der war und der kommt*, der Allmächtige*.", footnotes: ["Alpha und Omega (A und O) sind der erste und der letzte Buchstabe des griech. Alphabets.\n℘ Kap. 21,6; 22,13", "℘ Kap. 4,8", "℘ 1Mo 17,1"] },
      { number: 9, text: "Ich, Johannes, euer Bruder und Mitteilhaber an der Bedrängnis und am Königtum und am Ausharren in Jesus*, war auf der Insel, die Patmos genannt wird, um des Wortes Gottes und des Zeugnisses Jesu willen*.", heading: "Auftrag an Johannes, die Offenbarung zu schreiben", footnotes: ["Die Wörter »Bedrängnis«, »Königtum« und »Ausharren« beziehen sich alle auf »in Jesus«; im Griech. steht nur ein Artikel.\n℘ 2Thes 1,4", "℘ V. 2"] },
      { number: 10, text: "Ich war* an des Herrn Tag* im Geist*, und ich hörte hinter mir eine laute Stimme wie von einer Posaune*,", footnotes: ["w. wurde", "w. an dem dem Herrn gehörenden Tag", "℘ Kap. 4,2; 21,10", "℘ Kap. 4,1; 2Mo 19,19; Ps 29,4"] },
      { number: 11, text: "die sprach: Was du siehst, schreibe in ein Buch* und sende es den sieben Gemeinden*: nach Ephesus und nach Smyrna und nach Pergamon und nach Thyatira und nach Sardes und nach Philadelphia und nach Laodizea!", footnotes: ["℘ Jer 36,2", "o. Versammlungen\n℘ V. 20; Kap. 22,16"] },
      { number: 12, text: "Und ich wandte mich um, die Stimme zu sehen, die mit mir redete, und als ich mich umwandte, sah ich sieben goldene Leuchter*,", footnotes: ["℘ Sach 4,2"] },
      { number: 13, text: "und inmitten der Leuchter* <einen>, gleich einem Menschensohn*, bekleidet mit einem bis zu den Füßen reichenden Gewand, und an der Brust umgürtet mit einem goldenen Gürtel,", footnotes: ["℘ Kap. 2,1", "℘ Kap. 14,14; Hes 1,26; Dan 7,13; 10,16"] },
      { number: 14, text: "sein Haupt aber und die Haare <waren> weiß wie weiße Wolle, wie Schnee*, und seine Augen wie eine Feuerflamme*,", footnotes: ["℘ Dan 7,9", "℘ Kap. 19,12; Dan 10,6"] },
      { number: 15, text: "und seine Füße gleich glänzendem Erz, als glühten sie im Ofen*, und seine Stimme wie das Rauschen vieler Wasser*,", footnotes: ["℘ Kap. 2,18; 10,1; Hes 1,27", "℘ Kap. 14,2; 19,6; Hes 1,24; 43,2"] },
      { number: 16, text: "und er hatte in seiner rechten Hand sieben Sterne*, und aus seinem Mund ging ein zweischneidiges, scharfes Schwert* hervor, und sein Angesicht <war>, wie die Sonne leuchtet in ihrer Kraft*.", footnotes: ["℘ Kap. 2,1; 3,1", "℘ Kap. 2,12.16; 19,15.21", "℘ Kap. 10,1; Mt 17,2"] },
      { number: 17, text: "Und als ich ihn sah, fiel ich zu seinen Füßen wie tot*. Und er legte seine Rechte auf mich und sprach: Fürchte dich nicht! Ich bin der Erste und der Letzte*", footnotes: ["℘ Dan 8,18; 10,8.9", "℘ Kap. 2,8; 22,13; Jes 44,6; 48,12"] },
      { number: 18, text: "und der Lebendige, und ich war* tot, und siehe, ich bin lebendig* von Ewigkeit zu Ewigkeit* und habe die Schlüssel des Todes und des Hades*.", footnotes: ["w. wurde", "℘ Mt 28,7", "℘ Hebr 7,16.24", "d. i. das Totenreich"] },
      { number: 19, text: "Schreibe nun, was du gesehen hast und was ist und was nach diesem geschehen wird*!", footnotes: ["o. im Begriff steht zu geschehen\n℘ V. 1"] },
      { number: 20, text: "<Was> das Geheimnis der sieben Sterne, die du auf meiner Rechten gesehen hast, und die sieben goldenen Leuchter <betrifft>*: Die sieben Sterne sind Engel der sieben Gemeinden*, und die sieben Leuchter sind sieben Gemeinden*.", footnotes: ["℘ Kap. 2,1", "o. Versammlungen", "o. Versammlungen\n℘ V. 11"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Dem Engel der Gemeinde* in Ephesus* schreibe: Dies sagt der, der die sieben Sterne in seiner Rechten hält, der inmitten der sieben goldenen Leuchter wandelt*:", heading: "Sendschreiben an Ephesus", footnotes: ["o. Versammlung; so auch weiter in Kap. 2 und 3", "℘ Eph 1,1", "℘ Kap. 1,13.16.20"] },
      { number: 2, text: "Ich kenne deine Werke* und deine Mühe und dein Ausharren*, und dass du Böse nicht ertragen kannst*; und du hast die geprüft, die sich Apostel nennen und es nicht sind, und hast sie als Lügner befunden*;", footnotes: ["℘ V. 19; Kap. 3,1.8.15; Hebr 6,10", "℘ 1Thes 1,3", "℘ Ps 139,21", "℘ 2Kor 11,13; 1Jo 4,1"] },
      { number: 3, text: "und du hast Ausharren* und hast <vieles> getragen um meines Namens willen* und bist nicht müde geworden.", footnotes: ["℘ 2Thes 1,4", "℘ Phil 1,29"] },
      { number: 4, text: "Aber ich habe gegen dich*, dass du deine erste Liebe verlassen hast*.", footnotes: ["℘ V. 14.20", "℘ Jer 2,2; Mt 24,12"] },
      { number: 5, text: "Denke nun daran, wovon du gefallen bist, und tue Buße* und tue die ersten Werke! Wenn aber nicht, so komme ich <zu> dir und werde deinen Leuchter von seiner Stelle wegrücken, wenn du nicht Buße tust*.", footnotes: ["℘ V. 16; Kap. 3,3.19", "℘ Jer 18,8"] },
      { number: 6, text: "Aber dies hast du, dass du die Werke der Nikolaiten* hasst, die auch ich hasse*.", footnotes: ["offensichtlich Anhänger einer Irrlehre; so auch V. 15\n℘ V. 15", "℘ Ps 139,21"] },
      { number: 7, text: "Wer ein Ohr hat, höre*, was der Geist den Gemeinden sagt*! Wer überwindet*, dem werde ich zu essen geben von dem Baum des Lebens*, welcher in dem Paradies Gottes ist*.", footnotes: ["℘ Kap. 13,9; Mt 11,15", "℘ V. 11.17.29; Kap. 3,6.13.22", "℘ V. 11.17.26; Kap. 3,5.12.21; 21,7", "℘ Kap. 22,2.14.19", "℘ 1Mo 2,9; 3,22.24; Lk 23,43"] },
      { number: 8, text: "Und dem Engel der Gemeinde in Smyrna schreibe: Dies sagt der Erste und der Letzte, der tot war* und wieder lebendig wurde*:", heading: "Sendschreiben an Smyrna", footnotes: ["o. starb", "℘ Kap. 1,17.18"] },
      { number: 9, text: "Ich kenne deine Bedrängnis und deine Armut — du bist aber reich* — und die Lästerung von denen, die sagen, sie seien Juden, und es nicht sind*, sondern eine Synagoge des Satans.", footnotes: ["℘ Jak 2,5", "℘ Kap. 3,9"] },
      { number: 10, text: "Fürchte dich nicht vor dem, was du leiden wirst*! Siehe, der Teufel wird <einige> von euch ins Gefängnis werfen*, damit ihr geprüft werdet, und ihr werdet Bedrängnis haben zehn Tage. Sei treu bis zum Tod! Und ich werde dir den Siegeskranz des Lebens* geben.", footnotes: ["o. zu leiden im Begriff stehst\n℘ 1Petr 3,14", "o. steht im Begriff . . . zu werfen\n℘ Lk 21,12", "℘ Jak 1,12"] },
      { number: 11, text: "Wer ein Ohr hat, höre, was der Geist den Gemeinden sagt*! Wer überwindet*, wird keinen Schaden erleiden von dem zweiten Tod*.", footnotes: ["℘ V. 7", "℘ Ps 139,21", "℘ Kap. 20,6.14; 21,8"] },
      { number: 12, text: "Und dem Engel der Gemeinde in Pergamon schreibe: Dies sagt der, der das zweischneidige, scharfe Schwert hat*:", heading: "Sendschreiben an Pergamon", footnotes: ["℘ Kap. 1,16"] },
      { number: 13, text: "Ich weiß, wo du wohnst; wo der Thron des Satans ist; und du hältst meinen Namen fest und hast den Glauben an mich* nicht verleugnet*, auch in den Tagen des Antipas, meines treuen Zeugen*, der bei euch, wo der Satan wohnt, ermordet worden ist.", footnotes: ["o. meinen Glauben", "℘ 1Tim 5,8", "℘ Apg 22,20"] },
      { number: 14, text: "Aber ich habe ein weniges gegen dich*, dass du solche dort hast, welche die Lehre Bileams* festhalten, der den Balak lehrte, eine Falle* vor die Söhne Israels hinzustellen, so dass sie Götzenopfer aßen und Unzucht* trieben*.", footnotes: ["℘ V. 4", "℘ 2Petr 2,15", "o. ein Ärgernis; o. einen Anlass zur Sünde", "o. Hurerei", "℘ 4Mo 25,1.2; 31,16"] },
      { number: 15, text: "So hast auch du solche, die in gleicher Weise die Lehre der Nikolaiten festhalten*.", footnotes: ["℘ V. 6; 2Petr 2,1"] },
      { number: 16, text: "Tu nun Buße*! Wenn aber nicht, so komme ich <zu> dir bald* und werde Krieg mit ihnen führen mit dem Schwert meines Mundes*.", footnotes: ["℘ V. 5", "w. schnell", "℘ Kap. 1,16"] },
      { number: 17, text: "Wer ein Ohr hat, höre, was der Geist den Gemeinden sagt*! Wer überwindet*, dem werde ich von dem verborgenen Manna geben*; und ich werde ihm einen weißen Stein geben und, auf den Stein geschrieben, einen neuen Namen*, den niemand kennt, als wer ihn empfängt.", footnotes: ["℘ V. 7", "℘ Kap. 1,16", "℘ Joh 6,31-33", "℘ Kap. 3,12; Jes 56,5; 62,2; 65,15"] },
      { number: 18, text: "Und dem Engel der Gemeinde in Thyatira schreibe: Dies sagt der Sohn Gottes*, der Augen* hat wie eine Feuerflamme und Füße* gleich glänzendem Erz*:", heading: "Sendschreiben an Thyatira", footnotes: ["℘ Lk 1,35", "w. seine Augen", "w. und seine Füße <sind>", "℘ Kap. 1,14.15"] },
      { number: 19, text: "Ich kenne deine Werke und deine Liebe und deinen Glauben und deinen Dienst und dein Ausharren* und <weiß, dass> deine letzten Werke mehr sind als die ersten.", footnotes: ["℘ V. 2.3"] },
      { number: 20, text: "Aber ich habe gegen dich*, dass du das Weib Isebel* gewähren lässt, die sich eine Prophetin nennt und meine Knechte* lehrt und verführt, Unzucht* zu treiben* und Götzenopfer zu essen*.", footnotes: ["℘ V. 4", "℘ 1Kö 16,31", "w. Sklaven", "o. Hurerei; so auch V. 21", "℘ 2Kö 9,22", "℘ 2Mo 34,15; 1Kor 10,20"] },
      { number: 21, text: "Und ich gab ihr Zeit, damit sie Buße tue, und sie will nicht Buße tun von ihrer Unzucht." },
      { number: 22, text: "Siehe, ich werfe sie aufs Bett* und die, welche Ehebruch mit ihr treiben, in große Bedrängnis, wenn sie nicht Buße tun von ihren* Werken*.", footnotes: ["o. aufs Krankenbett", "d. h. Isebels", "℘ Lk 13,3"] },
      { number: 23, text: "Und ihre* Kinder werde ich mit dem Tod* töten, und alle Gemeinden werden erkennen, dass ich es bin, der Nieren und Herzen erforscht*; und ich werde euch einem jeden nach euren Werken geben*.", footnotes: ["d. h. Isebels", "wahrscheinlich eine tödliche Seuche", "℘ Ps 7,10; Jer 11,20; Joh 2,25; Apg 1,24", "℘ Kap. 20,12.13; 22,12; Ps 62,13; Jer 17,10; 25,14; Mt 16,27; Röm 2,6; 2Tim 4,14"] },
      { number: 24, text: "Euch aber sage ich, den Übrigen in Thyatira, allen, die diese Lehre nicht haben, welche die Tiefen des Satans, wie sie es nennen, nicht erkannt haben: Ich werfe keine andere Last auf euch*.", footnotes: ["℘ Apg 15,28"] },
      { number: 25, text: "Doch was ihr habt, haltet fest, bis ich komme*!", footnotes: ["℘ Kap. 3,11"] },
      { number: 26, text: "Und wer überwindet* und meine Werke bis ans Ende bewahrt*, dem werde ich Macht* über die Nationen geben*;", footnotes: ["℘ V. 7", "℘ Hebr 3,14", "o. Vollmacht", "℘ 1Kor 6,2"] },
      { number: 27, text: "und er wird sie hüten mit eisernem Stab*, wie Töpfergefäße zerschmettert werden*,", footnotes: ["℘ Kap. 12,5; 19,15", "℘ Ps 2,9"] },
      { number: 28, text: "wie auch ich von meinem Vater empfangen habe; und ich werde ihm den Morgenstern geben*.", footnotes: ["℘ Kap. 22,16; 2Petr 1,19"] },
      { number: 29, text: "Wer ein Ohr hat, höre, was der Geist den Gemeinden sagt*!", footnotes: ["℘ V. 7"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und dem Engel der Gemeinde in Sardes schreibe: Dies sagt der, der die sieben Geister* Gottes und die sieben Sterne* hat: Ich kenne deine Werke*, dass du den Namen hast, dass du lebst, und bist tot*.", heading: "Sendschreiben an Sardes", footnotes: ["℘ Kap. 1,4", "℘ Kap. 1,16", "℘ Kap. 2,2; Ps 33,15", "℘ 1Tim 5,6"] },
      { number: 2, text: "Wach auf und stärke das Übrige, das im Begriff stand zu sterben! Denn ich habe vor meinem Gott deine Werke nicht als völlig befunden." },
      { number: 3, text: "Denke nun daran, wie du empfangen und gehört hast, und bewahre es und tue Buße*! Wenn du nun nicht wachst*, werde ich kommen wie ein Dieb*, und du wirst nicht wissen, zu welcher Stunde ich über dich kommen werde.", footnotes: ["℘ Kap. 2,5", "℘ Mt 24,42.43", "℘ Kap. 16,15; 1Thes 5,2"] },
      { number: 4, text: "Aber du hast einige wenige Namen* in Sardes, die ihre Kleider nicht besudelt haben*; und sie werden mit mir einhergehen in weißen <Kleidern>*, denn sie sind es wert*.", footnotes: ["o. Personen", "℘ Jud 23", "℘ Kap. 4,4; 6,11; 7,9.13; 19,8", "o. würdig"] },
      { number: 5, text: "Wer überwindet*, der wird so mit weißen Kleidern* bekleidet werden, und ich werde seinen Namen aus dem Buch des Lebens* nicht auslöschen und seinen Namen bekennen vor meinem Vater und vor seinen Engeln*.", footnotes: ["℘ Kap. 2,7", "℘ Kap. 4,4; 6,11; 7,9.13; 19,8", "℘ Kap. 13,8; 17,8; 20,12.15; 21,27; Lk 10,20", "℘ Mt 10,32"] },
      { number: 6, text: "Wer ein Ohr hat, höre, was der Geist den Gemeinden sagt*!", footnotes: ["℘ Kap. 2,7"] },
      { number: 7, text: "Und dem Engel der Gemeinde in Philadelphia schreibe: Dies sagt der Heilige*, der Wahrhaftige*, der den Schlüssel Davids hat, der öffnet, und niemand wird schließen, und schließt, und niemand wird öffnen*:", heading: "Sendschreiben an Philadelphia", footnotes: ["℘ Lk 1,35", "℘ Kap. 6,10; 1Jo 5,20", "℘ Hi 12,14; Jes 22,22"] },
      { number: 8, text: "Ich kenne deine Werke*. Siehe, ich habe eine geöffnete Tür* vor dir gegeben, die niemand schließen kann; denn du hast eine kleine Kraft und hast mein Wort bewahrt* und hast meinen Namen nicht verleugnet.", footnotes: ["℘ Kap. 2,2", "℘ 1Kor 16,9", "℘ Joh 17,6; 1Tim 6,14"] },
      { number: 9, text: "Siehe, ich gebe* <Leute> aus der Synagoge des Satans, von denen, die sich Juden nennen und es nicht sind*, sondern lügen; siehe, ich werde sie dahin bringen, dass sie kommen und sich niederwerfen vor deinen Füßen* und erkennen, dass ich dich geliebt habe*.", footnotes: ["o. gebe dahin", "℘ Kap. 2,9", "℘ Jes 45,14; 49,23; 60,14", "℘ Jes 43,4"] },
      { number: 10, text: "Weil du das Wort vom Harren auf mich* bewahrt hast*, werde auch ich dich bewahren vor der Stunde der Versuchung, die über den ganzen Erdkreis kommen wird*, um die zu versuchen, die auf der Erde wohnen*.", footnotes: ["o. von meinem Ausharren", "℘ Kap. 14,12", "o. im Begriff steht . . . zu kommen\n℘ Kap. 7,14; 2Petr 2,9", "℘ Kap. 6,10; 8,13; 11,10; 13,8.14; 14,6; 17,8"] },
      { number: 11, text: "Ich komme bald*. Halte fest, was du hast*, damit niemand deinen Siegeskranz nehme*!", footnotes: ["w. schnell\n℘ Kap. 22,7.12.20; Hebr 10,37", "℘ Kap. 2,25", "℘ Kap. 4,4"] },
      { number: 12, text: "Wer überwindet*, den werde ich im Tempel meines Gottes* zu einer Säule machen, und er wird nie mehr hinausgehen; und ich werde auf ihn schreiben den Namen meines Gottes und den Namen der Stadt meines Gottes, des neuen Jerusalem*, das aus dem Himmel herabkommt von meinem Gott, und meinen neuen Namen*.", footnotes: ["℘ Kap. 2,7", "℘ 1Kor 3,16", "℘ Kap. 21,2.10; Hebr 12,22", "℘ Kap. 2,17; 14,1; 22,4"] },
      { number: 13, text: "Wer ein Ohr hat, höre, was der Geist den Gemeinden sagt*!", footnotes: ["℘ Kap. 2,7"] },
      { number: 14, text: "Und dem Engel der Gemeinde in Laodizea* schreibe: Dies sagt, der »Amen«* <heißt>, der treue und wahrhaftige Zeuge*, der Anfang* der Schöpfung Gottes*:", heading: "Sendschreiben an Laodizea", footnotes: ["℘ Kol 2,1", "Beteuerungsformel für die Wahrhaftigkeit des Gesagten; in den Evangelien am Anfang feierlicher Erklärungen Jesu mit »Wahrlich!« übersetzt; vgl. Kap. 22,20\n℘ 2Kor 1,20", "℘ Kap. 1,5; 19,11", "o. der Ursprung", "℘ Kol 1,15-17"] },
      { number: 15, text: "Ich kenne deine Werke*, dass du weder kalt noch heiß bist. Ach, dass du kalt oder heiß wärest*!", footnotes: ["℘ Kap. 2,2", "℘ 1Kö 18,21"] },
      { number: 16, text: "Also, weil du lau bist und weder heiß noch kalt, werde ich dich ausspeien aus meinem Munde." },
      { number: 17, text: "Weil du sagst: Ich bin reich und bin reich geworden und brauche nichts*!, und nicht weißt, dass du der Elende und bemitleidenswert und arm und blind* und bloß* bist,", footnotes: ["℘ Hos 12,9; 1Kor 4,8", "℘ Joh 9,40", "℘ 2Kor 5,3"] },
      { number: 18, text: "rate ich dir, von mir im Feuer geläutertes Gold zu kaufen*, damit du reich wirst*; und weiße Kleider, damit du bekleidet wirst und die Schande deiner Blöße nicht offenbar werde*; und Augensalbe, deine Augen zu salben, damit du siehst.", footnotes: ["℘ Jes 55,1", "℘ Spr 8,18; 2Kor 8,9", "℘ Kap. 16,15"] },
      { number: 19, text: "Ich überführe und züchtige alle, die ich liebe*. Sei nun eifrig und tu Buße*!", footnotes: ["℘ Hebr 12,6", "℘ Kap. 2,5"] },
      { number: 20, text: "Siehe, ich stehe an der Tür und klopfe an*; wenn jemand meine Stimme hört und die Tür öffnet, zu dem werde ich hineingehen und mit ihm essen und er mit mir.", footnotes: ["℘ Hl 5,2"] },
      { number: 21, text: "Wer überwindet*, dem werde ich geben, mit mir auf meinem Thron zu sitzen*, wie auch ich überwunden* und mich mit meinem Vater auf seinen Thron gesetzt habe*.", footnotes: ["℘ Kap. 2,7", "℘ Hi 36,7", "℘ Joh 16,33", "℘ Hebr 8,1"] },
      { number: 22, text: "Wer ein Ohr hat, höre, was der Geist den Gemeinden sagt*!", footnotes: ["℘ Kap. 2,7"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Nach diesem sah ich: Und siehe, eine Tür, geöffnet im Himmel*, und die erste Stimme, die ich gehört hatte wie die einer Posaune*, die mit mir redete, sprach: Komm hier herauf! Und ich werde dir zeigen, was nach diesem geschehen muss*.", heading: "Der Thron Gottes", footnotes: ["℘ Kap. 19,11; Hes 1,1", "℘ Kap. 1,10", "℘ Kap. 1,1"] },
      { number: 2, text: "Sogleich war* ich im Geist*: Und siehe, ein Thron stand im Himmel, und auf dem Thron saß einer*.", footnotes: ["w. wurde", "℘ Kap. 1,10", "℘ Kap. 5,13; 6,16; 7,10; 19,4; 20,11; 21,5; Ps 47,9; Jes 6,1; Hes 1,26; 10,1"] },
      { number: 3, text: "Und der da saß, <war> von Ansehen gleich einem Jaspisstein und einem Sarder*, und ein Regenbogen <war> rings um den Thron, von Ansehen gleich einem Smaragd*.", footnotes: ["℘ Kap. 21,11", "℘ Hes 1,28"] },
      { number: 4, text: "Und rings um den Thron <sah ich> vierundzwanzig Throne, und auf den Thronen saßen vierundzwanzig Älteste*, bekleidet mit weißen Kleidern*, und auf ihren Häuptern goldene Siegeskränze*.", footnotes: ["℘ Jes 24,23", "℘ Kap. 3,4.5", "℘ Kap. 3,11"] },
      { number: 5, text: "Und aus dem Thron gehen hervor Blitze und Stimmen und Donner*; und sieben Feuerfackeln brennen vor dem Thron*, welche die sieben Geister Gottes sind*.", footnotes: ["℘ Kap. 8,5; 10,3; 11,19; 16,18", "℘ Hes 1,13", "℘ Kap. 1,4; Sach 4,2"] },
      { number: 6, text: "Und vor dem Thron <war es> wie ein gläsernes Meer*, gleich Kristall*; und inmitten des Thrones und rings um den Thron vier lebendige Wesen, voller Augen vorn und hinten*.", footnotes: ["℘ Kap. 15,2", "℘ Hes 1,22", "℘ Hes 1,5.18"] },
      { number: 7, text: "Und das erste lebendige Wesen <war> gleich einem Löwen und das zweite lebendige Wesen gleich einem jungen Stier, und das dritte lebendige Wesen hatte das Angesicht wie das eines Menschen, und das vierte lebendige Wesen <war> gleich einem fliegenden Adler*.", footnotes: ["℘ Hes 1,10; 10,14"] },
      { number: 8, text: "Und die vier lebendigen Wesen hatten, eines wie das andere, je sechs Flügel und <sind> ringsum und inwendig voller Augen*, und sie hören Tag und Nacht nicht auf zu sagen: Heilig, heilig, heilig, Herr, Gott*, Allmächtiger, der war und der ist und der kommt*!", footnotes: ["℘ Hes 10,12", "℘ Jes 6,2.3", "℘ Kap. 1,4; Sach 4,2"] },
      { number: 9, text: "Und wenn die lebendigen Wesen Herrlichkeit und Ehre und Danksagung geben werden dem, der auf dem Thron sitzt, der da lebt von Ewigkeit zu Ewigkeit*,", footnotes: ["w. in die Zeitalter der Zeitalter (griech. Äonen); so auch V. 10\n℘ Kap. 10,6; 15,7; 5Mo 32,40; Dan 4,31; 6,27; 12,7"] },
      { number: 10, text: "so werden die vierundzwanzig Ältesten niederfallen vor dem, der auf dem Thron sitzt*, und den anbeten*, der von Ewigkeit zu Ewigkeit lebt, und werden ihre Siegeskränze niederwerfen vor dem Thron und sagen:", footnotes: ["℘ Kap. 5,13.14; 7,11; 11,16; 19,4", "o. huldigen; so auch nachher"] },
      { number: 11, text: "Du bist würdig, unser Herr und Gott, die Herrlichkeit und die Ehre und die Macht zu nehmen*, denn du hast alle Dinge erschaffen, und deines Willens wegen waren sie und sind sie erschaffen worden*.", footnotes: ["℘ Kap. 5,12; 7,12", "℘ Röm 11,36"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und ich sah in* der Rechten dessen, der auf dem Thron saß*, ein Buch, innen und auf der Rückseite beschrieben*, mit sieben Siegeln versiegelt*.", heading: "Das Buch mit den sieben Siegeln", footnotes: ["w. auf", "o. sitzt; so auch V. 7", "℘ Hes 2,9.10", "℘ Jes 29,11; Dan 12,4.9"] },
      { number: 2, text: "Und ich sah einen starken Engel*, der mit lauter Stimme ausrief: Wer ist würdig, das Buch zu öffnen und seine Siegel zu brechen?", footnotes: ["℘ Kap. 10,1; 18,1; Ps 103,20"] },
      { number: 3, text: "Und niemand in dem Himmel, auch nicht auf der Erde, auch nicht unter der Erde konnte das Buch öffnen noch es anblicken*.", footnotes: ["o. hineinsehen"] },
      { number: 4, text: "Und ich weinte sehr, weil niemand <für> würdig befunden wurde, das Buch zu öffnen noch es anzublicken*.", footnotes: ["o. hineinzusehen"] },
      { number: 5, text: "Und einer von den Ältesten spricht zu mir: Weine nicht! Siehe, es hat überwunden der Löwe aus dem Stamm Juda*, die Wurzel Davids*, um das Buch und seine sieben Siegel zu öffnen.", footnotes: ["℘ 1Mo 49,9.10; Hebr 7,14", "℘ Kap. 22,16; Jes 11,1.10; Röm 15,12"] },
      { number: 6, text: "Und ich sah inmitten des Thrones und der vier lebendigen Wesen und inmitten der Ältesten ein Lamm* stehen wie geschlachtet*, das sieben Hörner und sieben Augen hatte; dies sind die sieben Geister Gottes*, ausgesandt über die ganze Erde.", heading: "Das Lamm ist würdig, die Siegel zu öffnen", footnotes: ["℘ Kap. 14,1; Joh 1,29", "℘ 1Kor 5,7", "℘ Kap. 1,4"] },
      { number: 7, text: "Und es kam und nahm <das Buch> aus der Rechten dessen, der auf dem Thron saß." },
      { number: 8, text: "Und als es das Buch nahm, fielen die vier lebendigen Wesen und die vierundzwanzig Ältesten nieder vor dem Lamm, und sie hatten ein jeder eine Harfe und goldene Schalen voller Räucherwerk; das sind die Gebete der Heiligen*.", footnotes: ["℘ Kap. 8,3.4; Ps 141,2"] },
      { number: 9, text: "Und sie singen ein neues Lied* und sagen: Du bist würdig, das Buch zu nehmen und seine Siegel zu öffnen; denn du bist geschlachtet worden und hast durch dein Blut* <Menschen> für Gott erkauft* aus jedem Stamm und jeder Sprache und jedem Volk und jeder Nation", footnotes: ["℘ Kap. 14,3; Ps 33,3; Jes 42,10", "℘ Apg 20,28", "℘ Kap. 14,4; Gal 4,5"] },
      { number: 10, text: "und hast sie unserem Gott zu einem Königtum* und zu Priestern gemacht*, und sie werden über die Erde* herrschen*!", footnotes: ["mit anderen Handschr.: zu Königen", "℘ Kap. 1,6", "o. auf der Erde", "℘ Kap. 20,4; 22,5"] },
      { number: 11, text: "Und ich sah: Und ich hörte eine Stimme vieler Engel rings um den Thron her und um die lebendigen Wesen und um die Ältesten*; und ihre Zahl war Zehntausende mal Zehntausende und Tausende mal Tausende*,", footnotes: ["℘ Kap. 7,11", "℘ 1Kö 22,19; Ps 103,21; Hebr 12,22"] },
      { number: 12, text: "die mit lauter Stimme sprachen: Würdig ist das Lamm, das geschlachtet worden ist*, zu empfangen die Macht und Reichtum und Weisheit und Stärke und Ehre und Herrlichkeit und Lobpreis*.", footnotes: ["℘ Kap. 13,8", "℘ Kap. 4,11; 1Chr 29,11"] },
      { number: 13, text: "Und jedes Geschöpf, das im Himmel und auf der Erde und unter der Erde* und auf dem Meer ist, und alles, was in ihnen ist, hörte ich sagen: Dem, der auf dem Thron sitzt*, und dem Lamm den Lobpreis und die Ehre und die Herrlichkeit und die Macht von Ewigkeit zu Ewigkeit*!", footnotes: ["℘ Phil 2,10", "℘ Kap. 4,2", "w. in die Zeitalter der Zeitalter (griech. Äonen)\n℘ Ps 111,10"] },
      { number: 14, text: "Und die vier lebendigen Wesen sprachen: Amen*! Und die Ältesten fielen nieder und beteten an*.", footnotes: ["Beteuerungsformel für die Wahrhaftigkeit des Gesagten; in den Evangelien am Anfang feierlicher Erklärungen Jesu mit »Wahrlich!« übersetzt; vgl. Kap. 22,20\n℘ Kap. 19,4", "℘ Kap. 4,10"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und ich sah, als das Lamm eines von den sieben Siegeln öffnete, und hörte eines von den vier lebendigen Wesen wie mit einer Donnerstimme sagen: Komm*!", heading: "Die Öffnung der ersten sechs Siegel", footnotes: ["Einige Handschr. fügen hier und in V. 3.5.7 hinzu: und sieh"] },
      { number: 2, text: "Und ich sah: Und siehe, ein weißes Pferd*, und der darauf saß, hatte einen Bogen; und ihm wurde ein Siegeskranz gegeben, und er zog aus, siegend und um zu siegen.", footnotes: ["℘ Kap. 19,11"] },
      { number: 3, text: "Und als es das zweite Siegel öffnete, hörte ich das zweite lebendige Wesen sagen: Komm!" },
      { number: 4, text: "Und es zog aus ein anderes, ein feuerrotes Pferd*; und dem, der darauf saß, ihm wurde gegeben, den Frieden von der Erde zu nehmen und <die Menschen dahin zu bringen>, dass sie einander schlachteten; und ihm wurde ein großes Schwert gegeben*.", footnotes: ["℘ Sach 1,8", "℘ Hes 21,14-16; Lk 21,9"] },
      { number: 5, text: "Und als es das dritte Siegel öffnete, hörte ich das dritte lebendige Wesen sagen: Komm! Und ich sah: Und siehe, ein schwarzes Pferd, und der darauf saß, hatte eine Waage in seiner Hand." },
      { number: 6, text: "Und ich hörte <etwas> wie eine Stimme inmitten der vier lebendigen Wesen, die sagte: Ein Maß* Weizen für einen Denar und drei Maß* Gerste für einen Denar*! Und dem Öl und dem Wein füge keinen Schaden zu!", footnotes: ["w. Choinix; d. i. der Bedarf eines Tages; s. Tabelle »Maße«", "w. Choinix; d. i. der Bedarf eines Tages; s. Tabelle »Maße«", "℘ Mk 13,8"] },
      { number: 7, text: "Und als es das vierte Siegel öffnete, hörte ich die Stimme des vierten lebendigen Wesens sagen: Komm!" },
      { number: 8, text: "Und ich sah: Und siehe, ein fahles Pferd*, und der darauf saß, dessen Name <ist> »Tod«; und der Hades* folgte ihm*. Und ihnen wurde Macht* gegeben über den vierten Teil der Erde, zu töten mit dem Schwert und mit Hunger und mit Tod* und durch die wilden Tiere der Erde*.", footnotes: ["℘ Sach 6,2.3", "d. i. das Totenreich", "w. mit ihm", "o. Vollmacht", "Wahrscheinlich ist eine tödliche Seuche gemeint.", "℘ Jer 14,12; 15,3; Hes 5,12; 14,21"] },
      { number: 9, text: "Und als es das fünfte Siegel öffnete, sah ich unter dem Altar die Seelen derer, die geschlachtet worden waren* um des Wortes Gottes und um des Zeugnisses willen, das sie hatten*.", footnotes: ["℘ Kap. 20,4", "℘ Kap. 1,2"] },
      { number: 10, text: "Und sie riefen mit lauter Stimme und sprachen: Bis wann*, heiliger und wahrhaftiger Herrscher*, richtest und rächst du nicht unser Blut* an denen, die auf der Erde wohnen*?", footnotes: ["℘ Ps 6,4", "w. Gebieter (griech. despotes)\n℘ Kap. 3,7", "℘ Kap. 19,2; 5Mo 32,43", "℘ Kap. 3,10"] },
      { number: 11, text: "Und es wurde ihnen einem jeden ein weißes Gewand gegeben*; und es wurde ihnen gesagt, dass sie noch eine kurze Zeit abwarten sollten, bis auch ihre Mitknechte und ihre Brüder vollendet seien*, die ebenso wie sie getötet werden sollten.", footnotes: ["℘ Kap. 3,4.5", "℘ Hebr 11,40"] },
      { number: 12, text: "Und ich sah, als es das sechste Siegel öffnete: Und es geschah ein großes Erdbeben*; und die Sonne wurde schwarz wie ein härener Sack, und der ganze Mond wurde wie Blut*,", footnotes: ["℘ Kap. 8,5", "℘ Jes 13,10; Hes 32,7.8; Mk 13,24"] },
      { number: 13, text: "und die Sterne des Himmels fielen auf die Erde*, wie ein Feigenbaum, geschüttelt von einem starken Wind, seine Feigen abwirft.", footnotes: ["℘ Kap. 8,10; 9,1; Mt 24,29"] },
      { number: 14, text: "Und der Himmel schwand dahin wie ein Buch, das zusammengerollt wird*, und jeder Berg und jede Insel wurden von ihren Stellen gerückt*.", footnotes: ["℘ Jes 34,4; Hebr 1,12", "℘ Kap. 16,20"] },
      { number: 15, text: "Und die Könige der Erde und die Großen und die Obersten* und die Reichen und die Mächtigen und jeder Sklave und Freie verbargen sich in die Höhlen und in die Felsen der Berge*;", footnotes: ["griech. Chiliarchen; d. h. Tausendschaftsführer", "℘ Jes 2,10.19.21; Jer 4,29"] },
      { number: 16, text: "und sie sagen zu den Bergen und zu den Felsen: Fallt auf uns* und verbergt uns vor dem Angesicht dessen, der auf dem Thron sitzt*, und vor dem Zorn des Lammes*!", footnotes: ["℘ Kap. 9,6; Lk 23,30", "℘ Kap. 4,2", "℘ Ps 2,12"] },
      { number: 17, text: "Denn gekommen ist der große Tag ihres Zorns*. Und wer vermag zu bestehen*?", footnotes: ["℘ Kap. 11,18; 15,1; Ps 110,5; Röm 1,18", "℘ Ps 76,8; Joe 2,11; Zef 1,14; Mal 3,2"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Nach diesem sah ich vier Engel auf den vier Ecken der Erde* stehen; die hielten die vier Winde* der Erde fest, damit kein Wind wehe auf der Erde noch auf dem Meer noch über irgendeinen Baum.", heading: "Die Erlösten aus Israel und allen Nationen", footnotes: ["℘ Kap. 20,8; Hes 7,2", "℘ Jer 49,36; Hes 37,9; Dan 7,2; Sach 6,5; Mt 24,31"] },
      { number: 2, text: "Und ich sah einen anderen Engel von Sonnenaufgang heraufsteigen, der das Siegel des lebendigen Gottes hatte; und er rief mit lauter Stimme den vier Engeln zu, denen gegeben worden war, der Erde und dem Meer Schaden zuzufügen," },
      { number: 3, text: "und sagte: Schadet nicht der Erde noch dem Meer noch den Bäumen*, bis wir die Knechte* unseres Gottes an ihren Stirnen versiegelt haben*.", footnotes: ["℘ Kap. 9,4", "w. Sklaven", "℘ Hes 9,4.6"] },
      { number: 4, text: "Und ich hörte die Zahl der Versiegelten: 144 000 Versiegelte, aus jedem Stamm der Söhne Israels*.", footnotes: ["℘ Kap. 14,1"] },
      { number: 5, text: "Aus dem Stamm Juda* 12 000 Versiegelte, aus dem Stamm Ruben* 12 000, aus dem Stamm Gad* 12 000,", footnotes: ["℘ 1Mo 29,35", "℘ 1Mo 29,32", "℘ 1Mo 30,11"] },
      { number: 6, text: "aus dem Stamm Asser* 12 000, aus dem Stamm Naftali* 12 000, aus dem Stamm Manasse* 12 000,", footnotes: ["℘ 1Mo 30,13", "℘ 1Mo 30,8", "℘ 1Mo 41,51"] },
      { number: 7, text: "aus dem Stamm Simeon* 12 000, aus dem Stamm Levi* 12 000, aus dem Stamm Issaschar* 12 000,", footnotes: ["℘ 1Mo 29,33", "℘ 1Mo 29,34", "℘ 1Mo 30,18"] },
      { number: 8, text: "aus dem Stamm Sebulon* 12 000, aus dem Stamm Josef* 12 000, aus dem Stamm Benjamin* 12 000 Versiegelte.", footnotes: ["℘ 1Mo 30,20", "℘ 1Mo 30,24", "℘ 1Mo 35,18"] },
      { number: 9, text: "Nach diesem sah ich: Und siehe, eine große Volksmenge, die niemand zählen konnte, aus jeder Nation und aus Stämmen und Völkern und Sprachen, stand vor dem Thron und vor dem Lamm, bekleidet mit weißen Gewändern* und Palmen in ihren Händen.", footnotes: ["℘ Kap. 3,4.5"] },
      { number: 10, text: "Und sie rufen mit lauter Stimme und sagen: Das Heil unserem Gott*, der auf dem Thron sitzt*, und dem Lamm!", footnotes: ["℘ Kap. 19,1", "℘ Kap. 4,2"] },
      { number: 11, text: "Und alle Engel standen rings um den Thron und die Ältesten und die vier lebendigen Wesen*, und sie fielen vor dem Thron auf ihre Angesichter und beteten Gott an", footnotes: ["℘ Kap. 4,10"] },
      { number: 12, text: "und sagten: Amen*! Den Lobpreis und die Herrlichkeit und die Weisheit und die Danksagung und die Ehre und die Macht und die Stärke unserem Gott von Ewigkeit zu Ewigkeit*! Amen*.", footnotes: ["Beteuerungsformel für die Wahrhaftigkeit des Gesagten; in den Evangelien am Anfang feierlicher Erklärungen Jesu mit »Wahrlich!« übersetzt; vgl. Kap. 22,20", "w. in die Zeitalter der Zeitalter (griech. Äonen)", "w. in die Zeitalter der Zeitalter (griech. Äonen)\n℘ Kap. 4,11; Ps 29,1.2; 41,14"] },
      { number: 13, text: "Und einer von den Ältesten begann und sprach zu mir: Diese, die mit weißen Gewändern bekleidet sind — wer sind sie, und woher sind sie gekommen?" },
      { number: 14, text: "Und ich sprach zu ihm: Mein Herr, du weißt es. Und er sprach zu mir: Diese sind es, die aus der großen Bedrängnis* kommen, und sie haben ihre Gewänder gewaschen und sie weiß gemacht im Blut des Lammes*.", footnotes: ["℘ Kap. 3,10; Jer 30,7; Mt 24,21", "℘ Kap. 1,5"] },
      { number: 15, text: "Darum sind sie vor dem Thron Gottes und dienen ihm Tag und Nacht in seinem Tempel*; und der auf dem Thron sitzt, wird über ihnen wohnen*.", footnotes: ["℘ Kap. 22,3", "℘ Kap. 21,3"] },
      { number: 16, text: "Sie werden nicht mehr hungern, auch werden sie nicht mehr dürsten*, noch wird die Sonne auf sie fallen noch irgendeine Glut*;", footnotes: ["℘ Joh 6,35", "℘ Ps 121,6; Jes 49,10"] },
      { number: 17, text: "denn das Lamm, das in der Mitte des Thrones ist, wird sie hüten* und sie leiten zu Wasserquellen des Lebens*, und Gott wird jede Träne von ihren Augen abwischen*.", footnotes: ["℘ Hes 34,23", "℘ Ps 23,1.2; Jer 2,13", "℘ Kap. 21,4; Jes 25,8; Mt 5,4"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und als es das siebente Siegel öffnete, entstand ein Schweigen im Himmel, etwa eine halbe Stunde*.", heading: "Das siebente Siegel und die sieben Posaunen", footnotes: ["℘ Hab 2,20; Sach 2,17"] },
      { number: 2, text: "Und ich sah die sieben Engel*, die vor Gott stehen*; und es wurden ihnen sieben Posaunen gegeben.", footnotes: ["℘ Kap. 15,1", "℘ Lk 1,19"] },
      { number: 3, text: "Und ein anderer Engel kam und stellte sich an den Altar, und er hatte ein goldenes Räucherfass; und es wurde ihm viel Räucherwerk gegeben, damit er es für die Gebete aller Heiligen auf den goldenen Altar gebe*, der vor dem Thron ist*.", footnotes: ["d. h. um dadurch den Gebeten der Heiligen vor Gott Wohlgeruch und Wirksamkeit zu verleihen", "℘ Kap. 5,8; Hebr 9,4"] },
      { number: 4, text: "Und der Rauch des Räucherwerks stieg mit den Gebeten der Heiligen auf aus der Hand des Engels vor Gott." },
      { number: 5, text: "Und der Engel nahm das Räucherfass und füllte es von dem Feuer des Altars* und warf es auf die Erde*; und es geschahen Donner und Stimmen und Blitze* und ein Erdbeben*.", footnotes: ["℘ 3Mo 16,12", "℘ Hes 10,2", "℘ Kap. 4,5", "℘ Kap. 6,12; 11,19; 16,18; 2Mo 19,16.18"] },
      { number: 6, text: "Und die sieben Engel*, welche die sieben Posaunen hatten, machten sich bereit, um zu posaunen.", footnotes: ["℘ Kap. 15,1"] },
      { number: 7, text: "Und der erste posaunte: und es kam Hagel* und Feuer, mit Blut vermischt*, und wurde auf die Erde geworfen*. Und der dritte Teil der Erde verbrannte, und der dritte Teil der Bäume verbrannte, und alles grüne Gras verbrannte*.", heading: "Die ersten vier Posaunen", footnotes: ["℘ Kap. 11,19; 16,21", "℘ Ps 78,47.48; Hes 38,22", "℘ Kap. 16,2; Joe 3,3", "℘ 2Mo 9,23-25"] },
      { number: 8, text: "Und der zweite Engel posaunte: Und <etwas> wie ein großer feuerflammender Berg wurde ins Meer geworfen; und der dritte Teil des Meeres wurde zu Blut*.", footnotes: ["℘ Kap. 11,6; 16,3; 2Mo 7,20.21; Ps 78,44"] },
      { number: 9, text: "Und es starb der dritte Teil der Geschöpfe im Meer, die Leben hatten, und der dritte Teil der Schiffe wurde zerstört." },
      { number: 10, text: "Und der dritte Engel posaunte: Und es fiel vom Himmel ein großer Stern*, brennend wie eine Fackel, und er fiel auf den dritten Teil der Ströme und auf die Wasserquellen*.", footnotes: ["℘ Kap. 6,13; Jes 14,12", "℘ Kap. 16,4"] },
      { number: 11, text: "Und der Name des Sternes heißt »Wermut«; und der dritte Teil der Wasser wurde zu Wermut, und viele der Menschen starben von den Wassern, weil sie bitter gemacht waren*.", footnotes: ["℘ 2Mo 15,23"] },
      { number: 12, text: "Und der vierte Engel posaunte: Und es wurde geschlagen der dritte Teil der Sonne* und der dritte Teil des Mondes und der dritte Teil der Sterne, so dass der dritte Teil von ihnen verfinstert wurde und der Tag seinen dritten Teil kein Licht* hatte und ebenso die Nacht*.", footnotes: ["℘ Kap. 16,8", "w. nicht schien", "℘ 2Mo 10,21; Joe 3,4; Lk 21,25"] },
      { number: 13, text: "Und ich sah: Und ich hörte einen Adler hoch oben am Himmel fliegen und mit lauter Stimme sagen: Wehe, wehe, wehe* denen, die auf der Erde wohnen*, wegen der übrigen Stimmen der Posaune der drei Engel, die posaunen werden!", footnotes: ["℘ Kap. 9,12; 11,14", "℘ Kap. 3,10"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und der fünfte Engel posaunte: Und ich sah einen Stern<, der> vom Himmel* auf die Erde gefallen <war>; und es wurde ihm der Schlüssel zum Schlund des Abgrundes gegeben*.", heading: "Die fünfte Posaune", footnotes: ["℘ Kap. 6,13", "℘ Kap. 20,1; 2Petr 2,4"] },
      { number: 2, text: "Und er öffnete den Schlund des Abgrundes; und ein Rauch stieg auf aus dem Schlund wie der Rauch eines großen Ofens*, und die Sonne und die Luft wurden von dem Rauch des Schlundes verfinstert*.", footnotes: ["℘ 1Mo 19,28; 2Mo 19,18", "℘ Kap. 16,10; Joe 2,2.10"] },
      { number: 3, text: "Und aus dem Rauch kamen Heuschrecken hervor* auf die Erde, und es wurde ihnen Macht* gegeben, wie die Skorpione der Erde Macht* haben.", footnotes: ["℘ 2Mo 10,12-15; Ps 78,46", "o. Vollmacht", "o. Vollmacht"] },
      { number: 4, text: "Und es wurde ihnen gesagt, dass sie nicht dem Gras der Erde, auch nicht irgendetwas Grünem, auch nicht irgendeinem Baum Schaden zufügen sollten*, sondern den Menschen, die nicht das Siegel Gottes an den Stirnen haben*.", footnotes: ["℘ Kap. 7,3", "℘ Kap. 15,1"] },
      { number: 5, text: "Und es wurde ihnen <der Befehl> gegeben, dass sie sie nicht töteten, sondern dass sie fünf Monate gequält würden; und ihre Qual war die Qual eines Skorpions, wenn er einen Menschen sticht." },
      { number: 6, text: "Und in jenen Tagen werden die Menschen den Tod suchen und werden ihn nicht finden und werden zu sterben begehren, und der Tod flieht vor ihnen*.", footnotes: ["℘ Kap. 6,16; Hi 3,21; Jer 8,3"] },
      { number: 7, text: "Und die Gestalten der Heuschrecken waren gleich zum Kampf gerüsteten Pferden*, und auf ihren Köpfen <war es> wie Siegeskränze gleich Gold, und ihre Angesichter <waren> wie Menschenangesichter*;", footnotes: ["℘ Joe 2,4.5", "℘ Joe 1,6"] },
      { number: 8, text: "und sie hatten Haare wie Frauenhaare, und ihre Zähne waren wie die von Löwen." },
      { number: 9, text: "Und sie hatten Panzer wie eiserne Panzer, und das Geräusch ihrer Flügel war wie das Geräusch von Wagen mit vielen Pferden, die in den Kampf laufen;" },
      { number: 10, text: "und sie haben Schwänze gleich Skorpionen und Stacheln, und ihre Macht* ist in ihren Schwänzen, den Menschen fünf Monate zu schaden*.", footnotes: ["o. Vollmacht", "℘ V. 19"] },
      { number: 11, text: "Sie haben über sich einen König, den Engel des Abgrundes; sein Name ist auf Hebräisch Abaddon, und im Griechischen hat er den Namen Apollyon*.", footnotes: ["d. h. Verderben, o. Verderber"] },
      { number: 12, text: "Das eine Wehe ist vorüber; siehe, es kommen noch zwei Wehe nach diesen Dingen*.", footnotes: ["℘ Kap. 8,13"] },
      { number: 13, text: "Und der sechste Engel posaunte: Und ich hörte eine Stimme aus den vier Hörnern des goldenen Altars*, der vor Gott ist,", heading: "Die sechste Posaune", footnotes: ["℘ 2Mo 30,1-3"] },
      { number: 14, text: "zu dem sechsten Engel, der die Posaune hatte, sagen*: Löse die vier Engel, die an dem großen Strom Euphrat gebunden sind.", footnotes: ["℘ Kap. 16,7"] },
      { number: 15, text: "Und die vier Engel wurden losgebunden, die auf Stunde und Tag und Monat und Jahr gerüstet waren, den dritten Teil* der Menschen zu töten.", footnotes: ["℘ Kap. 8,7-12"] },
      { number: 16, text: "Und die Zahl der Truppen zu Pferde <war> zweimal zehntausend mal zehntausend; ich hörte ihre Zahl." },
      { number: 17, text: "Und so sah ich im Gesicht die Rosse und die, welche auf ihnen saßen: Sie hatten feurige und hyazinthfarbene und schwefelgelbe Panzer; und die Köpfe der Rosse waren wie Löwenköpfe, und aus ihren Mäulern geht Feuer und Rauch und Schwefel hervor." },
      { number: 18, text: "Von diesen drei Plagen wurde der dritte Teil* der Menschen getötet, von dem Feuer und dem Rauch und dem Schwefel, die aus ihren Mäulern hervorkamen.", footnotes: ["℘ Kap. 8,7-12"] },
      { number: 19, text: "Denn die Macht* der Rosse ist in ihrem Maul und in ihren Schwänzen; denn ihre Schwänze sind gleich Schlangen und haben Köpfe, und mit ihnen fügen sie Schaden zu*.", footnotes: ["o. Vollmacht", "℘ V. 10"] },
      { number: 20, text: "Und die Übrigen der Menschen, die durch diese Plagen nicht getötet wurden, taten auch nicht Buße* von den Werken ihrer Hände, nicht <mehr> anzubeten die Dämonen und die goldenen und die silbernen und die bronzenen und die steinernen und die hölzernen Götzenbilder*, die weder sehen noch hören noch wandeln können*.", footnotes: ["℘ Kap. 16,9.11; Jer 8,5.6", "℘ Jes 2,8.20", "℘ Ps 115,4-7; Dan 5,4.23"] },
      { number: 21, text: "Und sie taten nicht Buße* von ihren Mordtaten noch von ihren Zaubereien noch von ihrer Unzucht* noch von ihren Diebstählen*.", footnotes: ["℘ Kap. 16,9.11; Jer 8,5.6", "o. Hurerei", "℘ 2Kö 9,22"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Und ich sah einen anderen starken Engel* aus dem Himmel herabkommen, bekleidet mit einer Wolke, und der Regenbogen <war> auf seinem Haupt*, und sein Angesicht <war> wie die Sonne*, und seine Füße <waren> wie Feuersäulen*;", heading: "Johannes empfängt ein Buch", footnotes: ["℘ Kap. 5,2", "℘ Hes 1,28", "℘ Kap. 1,16", "℘ Kap. 1,15"] },
      { number: 2, text: "und er hatte in seiner Hand ein geöffnetes Büchlein*. Und er stellte seinen rechten Fuß auf das Meer, den linken aber auf die Erde;", footnotes: ["℘ Hes 2,9"] },
      { number: 3, text: "und er rief mit lauter Stimme, wie ein Löwe brüllt*. Und als er rief, ließen die sieben Donner ihre Stimmen vernehmen*.", footnotes: ["℘ Hos 11,10", "℘ Kap. 4,5"] },
      { number: 4, text: "Und als die sieben Donner redeten, wollte ich schreiben; und ich hörte eine Stimme aus dem Himmel sagen: Versiegle, was die sieben Donner geredet haben, und schreibe dies nicht*!", footnotes: ["℘ Kap. 22,10; Dan 8,26; 12,4.9"] },
      { number: 5, text: "Und der Engel, den ich auf dem Meer und auf der Erde stehen sah, erhob seine rechte Hand zum Himmel*", footnotes: ["℘ 5Mo 32,40; Dan 12,7"] },
      { number: 6, text: "und schwor bei dem, der von Ewigkeit zu Ewigkeit* lebt*, der den Himmel erschuf und <das,> was in ihm ist, und die Erde und <das,> was auf ihr ist, und das Meer und <das,> was in ihm ist*: Es wird keine Frist* mehr sein*,", footnotes: ["w. in die Zeitalter der Zeitalter (griech. Äonen)", "℘ Kap. 4,9", "℘ Kap. 14,7; Apg 4,24", "o. kein Aufschub, keine Zeit", "℘ Hes 12,28"] },
      { number: 7, text: "sondern in den Tagen der Stimme des siebenten Engels, wenn er posaunen wird*, wird auch das Geheimnis Gottes vollendet sein, wie er es seinen eigenen Knechten*, den Propheten*, als gute Botschaft verkündigt hat.", footnotes: ["℘ Kap. 11,15", "w. Sklaven", "℘ Kap. 11,18; Dan 9,6.10; Am 3,7; Sach 1,6; Apg 3,21"] },
      { number: 8, text: "Und die Stimme, die ich aus dem Himmel hörte, redete wieder mit mir und sprach: Gehe hin, nimm das geöffnete Buch in der Hand des Engels, der auf dem Meer und auf der Erde steht!" },
      { number: 9, text: "Und ich ging zu dem Engel und sagte ihm, er möge mir das Büchlein geben. Und er spricht zu mir: Nimm es und iss es auf*! Und es wird deinen Bauch bitter machen, aber in deinem Mund wird es süß sein wie Honig*.", footnotes: ["℘ Hes 2,8", "℘ Hes 3,1-3"] },
      { number: 10, text: "Und ich nahm das Büchlein aus der Hand des Engels und aß es auf; und es war in meinem Mund süß wie Honig, und als ich es gegessen hatte, wurde mein Bauch bitter gemacht." },
      { number: 11, text: "Und sie sagen mir: Du musst wieder weissagen über Völker und Nationen und Sprachen und viele Könige." },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und es wurde mir ein Rohr*, gleich einem Stab, gegeben und gesagt: Steh auf und miss den Tempel Gottes* und den Altar und die, welche darin anbeten!", heading: "Tod und Auferstehung der zwei Zeugen", footnotes: ["℘ Kap. 21,15", "℘ Hes 42,15"] },
      { number: 2, text: "Und den Hof, der außerhalb des Tempels ist, lass aus* und miss ihn nicht! Denn er ist den Nationen gegeben worden, und sie werden die heilige Stadt* zertreten* 42 Monate*.", footnotes: ["w. wirf hinaus", "℘ Kap. 21,2; Mt 4,5", "℘ Sach 12,3; Lk 21,24", "℘ Kap. 13,5; Dan 7,25; 12,7"] },
      { number: 3, text: "Und ich werde meinen zwei Zeugen* <Vollmacht> geben, und sie werden 1 260 Tage weissagen*, mit Sacktuch bekleidet.", footnotes: ["℘ 5Mo 19,15", "℘ Kap. 12,6.14"] },
      { number: 4, text: "Diese sind die zwei Ölbäume und die zwei Leuchter, die vor dem Herrn der Erde stehen*.", footnotes: ["℘ Sach 4,3.11-14"] },
      { number: 5, text: "Und wenn jemand ihnen schaden will, so geht Feuer aus ihrem Mund* und verzehrt ihre Feinde*; und wenn jemand ihnen schaden will, muss er ebenso getötet werden.", footnotes: ["℘ 2Sam 22,9", "℘ 2Kö 1,10-12; Jer 5,14"] },
      { number: 6, text: "Diese haben die Macht*, den Himmel zu verschließen, damit während der Tage ihrer Weissagung kein Regen falle*; und sie haben Gewalt über die Wasser, sie in Blut zu verwandeln*, und die Erde zu schlagen mit jeder Plage, sooft sie nur wollen.", footnotes: ["o. Vollmacht", "℘ 1Kö 17,1", "℘ Kap. 8,8"] },
      { number: 7, text: "Und wenn sie ihr Zeugnis vollendet haben werden, wird das Tier, das aus dem Abgrund heraufsteigt*, Krieg mit ihnen führen und wird sie überwinden und sie töten*.", footnotes: ["℘ Kap. 13,1; 17,8", "℘ Kap. 13,7; Dan 7,3.7.21"] },
      { number: 8, text: "Und ihr Leichnam <wird> auf der Straße der großen Stadt* <liegen>, die, geistlich gesprochen, Sodom* und Ägypten heißt, wo auch ihr Herr gekreuzigt wurde*.", footnotes: ["℘ Kap. 16,19", "℘ 1Mo 13,13; Jes 1,9.10", "℘ Joh 19,17"] },
      { number: 9, text: "Und <viele> aus den Völkern und Stämmen und Sprachen und Nationen sehen ihren Leichnam drei Tage und einen halben und erlauben nicht, ihre Leichname ins Grab zu legen*.", footnotes: ["℘ Ps 79,2.3"] },
      { number: 10, text: "Und die auf der Erde wohnen*, freuen sich über sie und sind fröhlich und werden einander Geschenke senden, denn diese zwei Propheten quälten die auf der Erde Wohnenden*.", footnotes: ["℘ Kap. 3,10", "℘ Ps 105,38"] },
      { number: 11, text: "Und nach den drei Tagen und einem halben kam der Geist des Lebens aus Gott in sie, und sie stellten sich auf ihre Füße*; und große Furcht befiel die, welche sie schauten.", footnotes: ["℘ Hes 37,10"] },
      { number: 12, text: "Und sie hörten eine laute Stimme aus dem Himmel zu ihnen sagen: Steigt hier herauf! Und sie stiegen in den Himmel hinauf in der Wolke*, und es schauten sie ihre Feinde.", footnotes: ["℘ Apg 1,9"] },
      { number: 13, text: "Und in jener Stunde geschah ein großes Erdbeben*, und der zehnte Teil der Stadt fiel, und siebentausend Menschennamen wurden in dem Erdbeben getötet; und die Übrigen gerieten in Furcht und gaben dem Gott des Himmels Ehre.", footnotes: ["℘ V. 19"] },
      { number: 14, text: "Das zweite Wehe ist vorüber; siehe, das dritte Wehe* kommt bald*.", footnotes: ["℘ Kap. 8,13", "w. schnell"] },
      { number: 15, text: "Und der siebente Engel posaunte*; und es geschahen laute Stimmen im Himmel, die sprachen: Das Reich* der Welt ist unseres Herrn und seines Christus geworden*, und er wird herrschen von Ewigkeit zu Ewigkeit*.", heading: "Der Beginn der Ereignisse der siebenten Posaune", footnotes: ["℘ Kap. 10,7", "o. Die Königsherrschaft", "o. unserem Herrn und seinem Christus zuteilgeworden\n℘ Kap. 12,10; 19,1; Ps 22,29; Dan 2,44; Ob 21; Sach 14,9; Mt 6,10", "w. in die Zeitalter der Zeitalter (griech. Äonen)\n℘ Ps 145,13; Dan 7,14.18.27"] },
      { number: 16, text: "Und die vierundzwanzig Ältesten, die vor Gott auf ihren Thronen sitzen, fielen auf ihre Angesichter und beteten Gott an*", footnotes: ["℘ Kap. 4,10; 19,4"] },
      { number: 17, text: "und sprachen: Wir danken dir, Herr, Gott, Allmächtiger, der ist und der war*, dass du deine große Macht ergriffen und deine Herrschaft angetreten hast*.", footnotes: ["℘ Kap. 1,4", "℘ Kap. 19,6; Ps 93,1"] },
      { number: 18, text: "Und die Nationen sind zornig gewesen*, und dein Zorn ist gekommen* und die Zeit der Toten, dass sie gerichtet werden und dass <du> den Lohn gibst deinen Knechten*, den Propheten*, und den Heiligen und denen, die deinen Namen fürchten*, den Kleinen* und den Großen*, und die <du> verdirbst, welche die Erde verderben*.", footnotes: ["℘ Ps 2,1-3", "℘ Kap. 6,17; Ps 2,5", "w. Sklaven", "℘ Kap. 10,7", "℘ Mal 3,16.20", "d. h. den Geringen", "℘ Kap. 19,5; Ps 115,13", "℘ Kap. 19,2"] },
      { number: 19, text: "Und der Tempel Gottes im Himmel wurde* geöffnet*, und die Lade seines Bundes wurde in seinem Tempel gesehen*; und es geschahen Blitze und Stimmen und Donner* und ein Erdbeben* und ein großer Hagel*.", footnotes: ["o. wurde im Himmel", "℘ Kap. 15,5", "℘ 2Mo 25,10; 1Kö 8,6", "℘ Kap. 4,5", "℘ V. 13; Kap. 8,5", "℘ Kap. 8,7"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und ein großes Zeichen erschien im* Himmel*: Eine Frau, bekleidet mit der Sonne, und der Mond <war> unter ihren Füßen und auf ihrem Haupt ein Kranz von zwölf Sternen.", heading: "Die Frau, ihr Kind und der Drache", footnotes: ["o. am", "℘ Kap. 15,1"] },
      { number: 2, text: "Und sie ist schwanger und schreit in Geburtswehen und in Schmerzen <und soll> gebären*.", footnotes: ["℘ Mi 4,10"] },
      { number: 3, text: "Und es erschien ein anderes Zeichen im* Himmel*: Und siehe, ein großer, feuerroter Drache, der sieben Köpfe und zehn Hörner* und auf seinen Köpfen sieben Diademe* hatte*;", footnotes: ["o. am", "℘ Kap. 15,1", "℘ Kap. 17,3", "Das Diadem, ein Stirnreif, war im Altertum das Zeichen der Königswürde.", "℘ Kap. 13,1"] },
      { number: 4, text: "und sein Schwanz zieht den dritten Teil der Sterne des Himmels fort, und er warf sie auf die Erde*. Und der Drache stand vor der Frau, die im Begriff war, zu gebären, um, wenn sie geboren hätte, ihr Kind zu verschlingen*.", footnotes: ["℘ Dan 8,10", "℘ Mt 2,13; 1Petr 5,8"] },
      { number: 5, text: "Und sie gebar einen Sohn, ein männliches <Kind>, der alle Nationen hüten soll mit eisernem Stab*; und ihr Kind wurde entrückt zu Gott und zu seinem Thron.", footnotes: ["℘ Kap. 2,27"] },
      { number: 6, text: "Und die Frau floh in die Wüste, wo sie eine von Gott bereitete Stätte hat, damit man sie dort ernähre 1 260 Tage*.", footnotes: ["℘ Kap. 11,2.3"] },
      { number: 7, text: "Und es entstand ein Kampf im Himmel: Michael und seine Engel kämpften mit dem Drachen*. Und der Drache kämpfte und seine Engel;", footnotes: ["℘ Jud 9"] },
      { number: 8, text: "und sie bekamen nicht die Übermacht, und ihre Stätte wurde nicht mehr im Himmel gefunden*.", footnotes: ["℘ Kap. 20,11; Dan 2,35"] },
      { number: 9, text: "Und es wurde geworfen der große Drache, die alte Schlange*, der Teufel und Satan genannt wird*, der den ganzen Erdkreis verführt*, geworfen wurde er auf die Erde, und seine Engel wurden mit ihm geworfen*.", footnotes: ["℘ 1Mo 3,1.14", "℘ Kap. 20,2", "℘ Kap. 20,3.8; 2Kor 11,3", "℘ Lk 10,18"] },
      { number: 10, text: "Und ich hörte eine laute Stimme im Himmel sagen: Nun ist das Heil und die Kraft und das Reich* unseres Gottes und die Macht* seines Christus gekommen* *; denn <hinab>geworfen ist der Verkläger unserer Brüder, der sie Tag und Nacht vor unserem Gott verklagte*.", footnotes: ["o. die Königsherrschaft", "o. Vollmacht", "w. geworden", "℘ Kap. 11,15", "℘ Hi 1,9.11; Sach 3,1"] },
      { number: 11, text: "Und sie haben ihn überwunden* wegen des Blutes des Lammes und wegen des Wortes ihres Zeugnisses, und sie haben ihr Leben nicht geliebt bis zum Tod*!", footnotes: ["℘ 1Jo 2,13", "℘ Lk 14,26"] },
      { number: 12, text: "Darum seid fröhlich, ihr Himmel* und die ihr in ihnen wohnt*! Wehe der Erde und dem Meer! Denn der Teufel ist zu euch hinabgekommen und hat große Wut, da er weiß, dass er <nur> eine kurze Zeit hat.", footnotes: ["℘ Jes 44,23; 49,13", "℘ Kap. 18,20; Phil 3,20"] },
      { number: 13, text: "Und als der Drache sah, dass er auf die Erde geworfen war, verfolgte er die Frau, die das männliche <Kind> geboren hatte." },
      { number: 14, text: "Und es wurden der Frau die zwei Flügel des großen Adlers gegeben, damit sie in die Wüste fliege, an ihre Stätte, wo sie ernährt wird eine Zeit und <zwei> Zeiten und eine halbe Zeit*, fern vom Angesicht der Schlange.", footnotes: ["Das Griech. macht deutlich, dass es sich um (von Gott) bestimmte, festgesetzte Zeiten oder Zeitabschnitte handelt.\n℘ V. 6"] },
      { number: 15, text: "Und die Schlange warf aus ihrem Mund Wasser wie einen Strom hinter der Frau her, um sie mit dem Strom fortzureißen*.", footnotes: ["℘ Jes 59,19"] },
      { number: 16, text: "Und die Erde half der Frau, und die Erde öffnete ihren Mund und verschlang den Strom, den der Drache aus seinem Mund warf." },
      { number: 17, text: "Und der Drache wurde zornig über die Frau und ging hin, Krieg zu führen mit den Übrigen ihrer Nachkommenschaft*, welche die Gebote Gottes halten* und das Zeugnis Jesu haben*.", footnotes: ["w. ihres Samens\n℘ 1Mo 3,15", "o. bewahren", "℘ Kap. 1,2"] },
      { number: 18, text: "Und er* stand auf dem Sand des Meeres.", heading: "Das Tier aus dem Meer und das Tier aus der Erde", footnotes: ["mit mehreren alten Handschr.: ich"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Und ich sah aus dem Meer ein Tier aufsteigen*, das zehn Hörner* und sieben Köpfe* hatte, und auf seinen Hörnern zehn Diademe*, und auf seinen Köpfen Namen der Lästerung.", footnotes: ["℘ Kap. 11,7", "℘ Kap. 17,3.7", "℘ Kap. 17,9", "Das Diadem, ein Stirnreif, war im Altertum das Zeichen der Königswürde.\n℘ Kap. 17,12"] },
      { number: 2, text: "Und das Tier*, das ich sah, war gleich einem Panther und seine Füße wie die eines Bären und sein Maul wie eines Löwen Maul*. Und der Drache gab ihm seine Kraft und seinen Thron und große Macht*.", footnotes: ["℘ Kap. 16,10; 19,19", "℘ Dan 7,4-7", "o. Vollmacht\n℘ Lk 4,6"] },
      { number: 3, text: "Und <ich sah> einen seiner Köpfe wie zum Tod geschlachtet. Und seine Todeswunde wurde geheilt, und die ganze Erde staunte hinter dem Tier her*.", footnotes: ["℘ Kap. 17,8"] },
      { number: 4, text: "Und sie beteten den Drachen an, weil er dem Tier die Macht* gab, und sie beteten das Tier an und sagten: Wer ist dem Tier gleich*? Und wer kann mit ihm kämpfen?", footnotes: ["o. Vollmacht", "℘ Ps 89,7"] },
      { number: 5, text: "Und es wurde ihm ein Mund gegeben, der große Dinge und Lästerungen redete*; und es wurde ihm Macht* gegeben*, 42 Monate zu wirken*.", footnotes: ["℘ Dan 7,8; 11,36", "o. Vollmacht", "℘ Dan 8,24", "℘ Kap. 11,2.3"] },
      { number: 6, text: "Und es öffnete seinen Mund zu Lästerungen gegen Gott*, um seinen Namen und sein Zelt <und> die, welche im Himmel wohnen, zu lästern.", footnotes: ["℘ 2Thes 2,4"] },
      { number: 7, text: "Und es wurde ihm gegeben, mit den Heiligen Krieg zu führen und sie zu überwinden*; und es wurde ihm Macht* gegeben über jeden Stamm und jedes Volk und jede Sprache und jede Nation.", footnotes: ["℘ Kap. 11,7", "o. Vollmacht"] },
      { number: 8, text: "Und alle, die auf der Erde wohnen*, werden ihn* anbeten, <jeder,> dessen Name nicht geschrieben ist im Buch des Lebens* des geschlachteten Lammes* von Grundlegung der Welt an.", footnotes: ["℘ Kap. 3,10", "d. h. das Tier. Hier wird deutlich, dass mit dem Tier eine Person gemeint ist.", "℘ Kap. 3,5", "℘ Kap. 5,6.12"] },
      { number: 9, text: "Wenn jemand ein Ohr hat, so höre er*!", footnotes: ["℘ Kap. 2,7"] },
      { number: 10, text: "Wenn jemand in Gefangenschaft <geht>, so geht er in Gefangenschaft*; wenn jemand mit dem Schwert getötet wird*, so muss er mit dem Schwert getötet werden*. Hier ist das Ausharren und der Glaube der Heiligen*.", footnotes: ["℘ Jer 43,11", "Andere gute Handschr. lesen: töten wird", "℘ Jer 15,2; Mt 26,52", "℘ Kap. 14,12; Hebr 6,12"] },
      { number: 11, text: "Und ich sah ein anderes Tier aus der Erde aufsteigen; und es hatte zwei Hörner gleich einem Lamm*, und es redete wie ein Drache.", footnotes: ["℘ Mt 7,15"] },
      { number: 12, text: "Und die ganze Macht* des ersten Tieres übt es vor ihm aus, und es veranlasst die Erde und die auf ihr wohnen, dass sie das erste Tier anbeten, dessen Todeswunde geheilt wurde*.", footnotes: ["o. Vollmacht", "℘ V. 3"] },
      { number: 13, text: "Und es tut große Zeichen*, dass es selbst Feuer vom Himmel vor den Menschen auf die Erde herabkommen lässt*;", footnotes: ["℘ Kap. 16,14; Mt 24,24", "℘ 1Kö 18,38.39"] },
      { number: 14, text: "und es verführt die, welche auf der Erde wohnen*, wegen der Zeichen*, die vor dem Tier zu tun ihm gegeben wurde*, und es sagt denen, die auf der Erde wohnen*, dem Tier, das* die Wunde des Schwertes hat und <wieder> lebendig geworden ist, ein Bild zu machen.", footnotes: ["℘ Kap. 3,10", "℘ 5Mo 13,2-4", "℘ Kap. 19,20", "℘ Kap. 3,10", "w. der; vgl. Anm. zu V. 8"] },
      { number: 15, text: "Und es wurde ihm gegeben, dem Bild des Tieres Odem* zu geben, so dass das Bild des Tieres sogar redete und bewirkte, dass alle getötet wurden, die das Bild des Tieres nicht anbeteten*.", footnotes: ["o. Geist", "℘ Dan 3,6"] },
      { number: 16, text: "Und es bringt alle dahin, die Kleinen* und die Großen, und die Reichen und die Armen, und die Freien und die Sklaven, dass man ihnen ein Malzeichen an ihre rechte Hand oder an ihre Stirn gibt*;", footnotes: ["d. h. die Geringen", "℘ Kap. 14,9; 19,20; 20,4"] },
      { number: 17, text: "und dass niemand kaufen oder verkaufen kann, als nur der, welcher das Malzeichen hat, den Namen des Tieres oder die Zahl seines Namens." },
      { number: 18, text: "Hier ist die Weisheit*. Wer Verständnis* hat, berechne die Zahl des Tieres*! Denn es ist eines Menschen Zahl; und seine Zahl ist 666*.", footnotes: ["℘ Kap. 17,9", "o. Verstand", "℘ Kap. 15,2", "Da in den alten Sprachen (Griech., Hebr.) die Buchstaben auch als Zahlen verwendet wurden, hatte jedes Wort auch einen Zahlenwert. Welches Wort sich hinter der Zahl 666 verbirgt, ist, obwohl viel diskutiert, unbekannt."] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Und ich sah: Und siehe, das Lamm* stand auf dem Berg Zion* und mit ihm 144 000*, die seinen Namen und den Namen seines Vaters an ihren Stirnen geschrieben trugen*.", heading: "Das Lamm und die Seinen", footnotes: ["℘ Kap. 5,6", "℘ Ps 2,6", "℘ Kap. 7,4", "℘ Kap. 3,12"] },
      { number: 2, text: "Und ich hörte eine Stimme aus dem Himmel wie das Rauschen vieler Wasser* und wie das Rollen eines lauten Donners*; und die Stimme, die ich hörte, war wie von Harfensängern, die auf ihren Harfen spielen.", footnotes: ["℘ Kap. 1,15", "℘ Kap. 19,6"] },
      { number: 3, text: "Und sie singen ein neues Lied* vor dem Thron und vor den vier lebendigen Wesen und den Ältesten; und niemand konnte das Lied lernen als nur die 144 000, die von der Erde erkauft waren.", footnotes: ["℘ Kap. 5,9; 15,3"] },
      { number: 4, text: "Diese sind es, die sich mit Frauen nicht befleckt haben, denn sie sind jungfräulich*; diese sind es, die dem Lamm folgen, wohin es auch geht*. Diese sind aus den Menschen als Erstlingsfrucht* für Gott und das Lamm erkauft worden*.", footnotes: ["℘ 2Kor 11,2", "℘ Joh 10,27; 1Petr 2,21", "Einige alte Handschr. lesen »von Anfang an« statt »als Erstlingsfrucht«.\n℘ Jer 2,3; Jak 1,18", "℘ Kap. 5,9; 1Kor 6,20"] },
      { number: 5, text: "Und in ihrem Mund wurde kein Falsch gefunden*; sie sind untadelig*.", footnotes: ["℘ Zef 3,13", "℘ Hl 4,7; Eph 5,27"] },
      { number: 6, text: "Und ich sah einen anderen Engel hoch oben am Himmel fliegen, der das ewige* Evangelium hatte, um es denen zu verkündigen*, die auf der Erde ansässig sind*, und jeder Nation und jedem Stamm und jeder Sprache und jedem Volk;", heading: "Ankündigung des Gerichts", footnotes: ["w. ein ewiges", "w. als gute Botschaft zu verkündigen", "℘ Kap. 3,10"] },
      { number: 7, text: "und er sprach mit lauter Stimme: Fürchtet Gott und gebt ihm Ehre*! Denn die Stunde seines Gerichts ist gekommen. Und betet den an, der den Himmel und die Erde und Meer und Wasserquellen gemacht hat*!", footnotes: ["℘ Jes 42,12; Jer 13,16", "℘ Kap. 10,6; Ps 95,5; 136,5.6"] },
      { number: 8, text: "Und ein anderer, zweiter Engel folgte und sprach: Gefallen, gefallen ist das große Babylon*, das mit dem Wein seiner leidenschaftlichen Unzucht* alle Nationen getränkt hat*.", footnotes: ["vielleicht verschlüsselte Bezeichnung für Rom, so auch im Folgenden\n℘ Kap. 16,19; 17,5; 18,2.10.21; Jes 21,9; Dan 4,27", "o. Hurerei", "℘ Kap. 17,2; 18,3; Jer 51,7"] },
      { number: 9, text: "Und ein anderer, dritter Engel folgte ihnen und sprach mit lauter Stimme: Wenn jemand das Tier und sein Bild anbetet und ein Malzeichen annimmt an seine Stirn oder an seine Hand*,", footnotes: ["℘ Kap. 13,16"] },
      { number: 10, text: "so wird auch er trinken vom Wein des Grimmes Gottes, der unvermischt im Kelch seines Zornes bereitet ist*; und er wird mit Feuer und Schwefel gequält werden* vor den heiligen Engeln und vor dem Lamm.", footnotes: ["℘ Kap. 16,19; 18,6; Ps 75,9; Jes 51,17; Jer 25,15", "℘ Kap. 19,20; 1Mo 19,24"] },
      { number: 11, text: "Und der Rauch ihrer Qual steigt auf von Ewigkeit zu Ewigkeit*; und sie haben keine Ruhe Tag und Nacht, die das Tier und sein Bild anbeten, und wenn jemand das Malzeichen seines Namens annimmt.", footnotes: ["w. in die Zeitalter der Zeitalter (griech. Äonen)\n℘ Kap. 19,3; 20,10; Jes 34,10; Mk 9,48"] },
      { number: 12, text: "Hier ist das Ausharren der Heiligen*, welche die Gebote Gottes und den Glauben Jesu bewahren*.", footnotes: ["℘ Kap. 3,10; 13,10", "℘ Kap. 1,2"] },
      { number: 13, text: "Und ich hörte eine Stimme aus dem Himmel sagen: Schreibe: Glückselig die Toten, die von jetzt an im Herrn sterben! Ja, spricht der Geist, damit sie ruhen von ihren Mühen*, denn ihre Werke folgen ihnen nach*.", footnotes: ["℘ Jes 57,2; Hebr 4,10", "w. mit ihnen\n℘ 1Tim 5,25"] },
      { number: 14, text: "Und ich sah: Und siehe, eine weiße Wolke, und auf der Wolke saß einer gleich einem Menschensohn*, der auf seinem Haupt einen goldenen Siegeskranz* und in seiner Hand eine scharfe Sichel hatte.", heading: "Ernte und Weinlese", footnotes: ["℘ Kap. 1,13", "℘ Ps 21,4"] },
      { number: 15, text: "Und ein anderer Engel kam aus dem Tempel hervor* und rief dem, der auf der Wolke saß, mit lauter Stimme zu: Schicke deine Sichel und ernte! Denn die Stunde des Erntens ist gekommen, denn die Ernte der Erde ist überreif* geworden*.", footnotes: ["℘ Kap. 15,6", "w. trocken, o. dürre (was die Überreife ausdrücken soll)", "℘ Mk 4,29"] },
      { number: 16, text: "Und der auf der Wolke saß, warf seine Sichel auf die Erde, und die Erde wurde abgeerntet*.", footnotes: ["℘ Mt 13,39"] },
      { number: 17, text: "Und ein anderer Engel kam aus dem Tempel im Himmel* hervor*, und auch er hatte eine scharfe Sichel.", footnotes: ["℘ Kap. 11,19", "℘ Kap. 15,6"] },
      { number: 18, text: "Und ein anderer Engel, der Macht* über das Feuer hatte, kam aus dem Altar hervor, und er rief dem, der die scharfe Sichel hatte, mit lauter Stimme zu und sprach: Schicke deine scharfe Sichel und lies die Trauben des Weinstocks der Erde! Denn seine Beeren sind reif geworden*.", footnotes: ["o. Vollmacht", "℘ Am 8,1.2"] },
      { number: 19, text: "Und der Engel warf seine Sichel auf die Erde und las den Weinstock der Erde ab und warf <die Trauben> in die große Kelter des Grimmes Gottes*.", footnotes: ["℘ Kap. 19,15; Joe 4,13"] },
      { number: 20, text: "Und die Kelter wurde außerhalb der Stadt getreten*, und Blut ging aus der Kelter hervor bis an die Zügel der Pferde, 1 600 Stadien* weit.", footnotes: ["℘ Jes 63,3; Kla 1,15", "das sind ca. 296 km"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und ich sah ein anderes Zeichen im Himmel*, groß und wunderbar: Sieben Engel*, die sieben Plagen hatten*, die letzten; denn in ihnen wurde der Grimm Gottes vollendet*.", heading: "Die sieben Engel mit den sieben Plagen", footnotes: ["℘ Kap. 12,1.3", "℘ Kap. 8,2.6", "℘ Kap. 21,9", "℘ Kap. 6,17"] },
      { number: 2, text: "Und ich sah <etwas> wie ein gläsernes Meer*, mit Feuer gemischt, und <sah> die Überwinder über das Tier und über sein Bild und über die Zahl seines Namens* an dem gläsernen Meer stehen, und sie hatten Harfen Gottes.", footnotes: ["℘ Kap. 4,6", "℘ Kap. 13,15-17"] },
      { number: 3, text: "Und sie singen das Lied Moses*, des Knechtes* Gottes, und das Lied des Lammes* und sagen: Groß und wunderbar <sind> deine Werke*, Herr, Gott, Allmächtiger! Gerecht und wahrhaftig <sind> deine Wege*, König der Nationen*!", footnotes: ["℘ 2Mo 15,1", "w. Sklaven", "℘ Kap. 14,3", "℘ 2Mo 34,10; Ps 92,6", "℘ Kap. 16,7; 19,2; 5Mo 32,4; Ps 111,2.3; 145,17", "℘ Ps 22,29; 47,9"] },
      { number: 4, text: "Wer sollte nicht fürchten*, Herr, und verherrlichen deinen Namen*? Denn du allein <bist> heilig*; denn alle Nationen werden kommen und vor dir anbeten*, weil deine gerechten Taten* offenbar geworden sind*.", footnotes: ["℘ Ps 33,8; Jer 10,7", "℘ Ps 45,18", "℘ 2Mo 15,11; Ps 99,3", "℘ Ps 22,28; 86,9; Mal 1,11", "o. Rechtsforderungen", "℘ Ps 98,2; Jer 16,19-21"] },
      { number: 5, text: "Und nach diesem sah ich: Und der Tempel des Zeltes des Zeugnisses* im Himmel wurde geöffnet*.", footnotes: ["℘ 4Mo 9,15", "℘ Kap. 11,19"] },
      { number: 6, text: "Und die sieben Engel, welche die sieben Plagen hatten, kamen aus dem Tempel hervor*, bekleidet mit reinem, glänzendem Leinen und um die Brust gegürtet mit goldenen Gürteln*.", footnotes: ["℘ Kap. 14,15.17", "℘ Kap. 1,13"] },
      { number: 7, text: "Und eines der vier lebendigen Wesen gab den sieben Engeln sieben goldene Schalen*, voll des Grimmes Gottes*, der da lebt von Ewigkeit zu Ewigkeit*.", footnotes: ["℘ Kap. 17,1", "℘ Kap. 16,1", "w. in die Zeitalter der Zeitalter (griech. Äonen)\n℘ Kap. 4,9"] },
      { number: 8, text: "Und der Tempel wurde mit Rauch gefüllt von der Herrlichkeit Gottes und von seiner Macht*; und niemand konnte in den Tempel eintreten*, bis die sieben Plagen der sieben Engel vollendet waren.", footnotes: ["℘ 2Mo 40,34; 1Kö 8,10; Jes 6,4; Hes 44,4", "℘ 2Chr 5,14"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und ich hörte eine laute Stimme aus dem Tempel* zu den sieben Engeln sagen: Geht hin und gießt die sieben Schalen des Grimmes Gottes aus auf die Erde*.", heading: "Ausgießung der sieben Zornschalen", footnotes: ["℘ V. 17; Jes 66,6", "℘ Kap. 15,7; Ps 69,25; Jer 10,25; Zef 3,8"] },
      { number: 2, text: "Und der erste ging hin und goss seine Schale aus auf die Erde*; und es entstand ein böses und schlimmes Geschwür* an den Menschen, die das Malzeichen des Tieres hatten und sein Bild anbeteten*.", footnotes: ["℘ Kap. 8,7", "℘ 2Mo 9,9; 5Mo 28,35", "℘ Kap. 13,16"] },
      { number: 3, text: "Und der zweite goss seine Schale aus auf das Meer; und es wurde <zu> Blut* wie von einem Toten, und jede lebendige Seele starb, <alles> was im Meer war.", footnotes: ["℘ Kap. 8,8"] },
      { number: 4, text: "Und der dritte goss seine Schale aus auf die Ströme und die Wasserquellen*, und es wurde <zu> Blut*.", footnotes: ["℘ Kap. 8,10", "℘ Kap. 8,8"] },
      { number: 5, text: "Und ich hörte den Engel der Wasser sagen: Du bist gerecht, der ist und der war*, der Heilige, dass du so gerichtet* hast.", footnotes: ["℘ Kap. 1,4", "o. geurteilt"] },
      { number: 6, text: "Denn Blut von Heiligen und Propheten haben sie vergossen*, und Blut hast du ihnen zu trinken gegeben*; sie sind es wert.", footnotes: ["℘ Kap. 17,6; 18,24; Ps 79,3", "℘ Jes 49,26"] },
      { number: 7, text: "Und ich hörte den Altar* sagen*: Ja, Herr, Gott, Allmächtiger, wahrhaftig und gerecht sind deine Gerichte*.", footnotes: ["d. h. vom Altar her", "℘ Kap. 9,13.14", "℘ Kap. 15,3; Ps 19,10"] },
      { number: 8, text: "Und der vierte goss seine Schale aus auf die Sonne; und es wurde ihr gegeben, die Menschen mit Feuer zu versengen*.", footnotes: ["℘ Kap. 8,12; Mal 3,19"] },
      { number: 9, text: "Und die Menschen wurden von großer Hitze versengt und lästerten den Namen Gottes, der über diese Plagen Macht* hat, und sie taten nicht Buße*, ihm Ehre zu geben.", footnotes: ["o. Vollmacht", "℘ Kap. 9,20; Jer 5,3"] },
      { number: 10, text: "Und der fünfte goss seine Schale aus auf den Thron des Tieres*; und sein Reich* wurde verfinstert*; und sie zerbissen ihre Zungen vor Schmerz", footnotes: ["℘ Kap. 13,1.2", "o. sein Königreich", "℘ Kap. 9,2; 2Mo 10,21.22"] },
      { number: 11, text: "und lästerten den Gott des Himmels* wegen ihrer Schmerzen und wegen ihrer Geschwüre, und sie taten nicht Buße* von ihren Werken.", footnotes: ["℘ Jes 8,21", "℘ Kap. 9,20; Jer 5,3"] },
      { number: 12, text: "Und der sechste goss seine Schale aus auf den großen Strom Euphrat; und sein Wasser vertrocknete*, damit der Weg der Könige von Sonnenaufgang her bereitet wurde.", footnotes: ["℘ Jes 11,15"] },
      { number: 13, text: "Und ich sah aus dem Mund des Drachen* und aus dem Mund des Tieres* und aus dem Mund des falschen Propheten* drei unreine Geister <kommen>, wie Frösche*;", footnotes: ["℘ Kap. 12,3", "℘ Kap. 13,1.2", "℘ Kap. 19,20; 20,10", "℘ 2Mo 7,28"] },
      { number: 14, text: "denn es sind Geister von Dämonen, die Zeichen tun*, die ausziehen zu den Königen des ganzen Erdkreises, sie zu versammeln zu dem Krieg des großen Tages Gottes, des Allmächtigen*.", footnotes: ["℘ Kap. 13,13", "℘ Kap. 17,14; 19,19"] },
      { number: 15, text: "— Siehe, ich komme wie ein Dieb*. Glückselig, der wacht* und seine Kleider bewahrt, damit er nicht nackt umhergehe und man nicht seine Schande sehe*! —", footnotes: ["℘ Kap. 3,3", "℘ Lk 12,37", "℘ Kap. 3,18"] },
      { number: 16, text: "Und er versammelte sie an den Ort, der auf Hebräisch Harmagedon* heißt.", footnotes: ["d. h. Berg von Megiddo; Ort wichtiger Schlachten in Israels alttestamentl. Geschichte"] },
      { number: 17, text: "Und der siebente goss seine Schale aus in die Luft; und es kam eine laute Stimme aus dem Tempel* vom Thron her, die sprach: Es ist geschehen*.", footnotes: ["℘ V. 1", "℘ Kap. 21,6"] },
      { number: 18, text: "Und es geschahen Blitze und Stimmen und Donner*; und ein großes Erdbeben geschah*, desgleichen nicht geschehen ist, seitdem ein Mensch auf der Erde war, ein so gewaltiges, so großes Erdbeben*.", footnotes: ["℘ Kap. 4,5", "℘ Kap. 8,5", "℘ Mk 13,19"] },
      { number: 19, text: "Und die Große Stadt* wurde in drei Teile <gespalten>, und die Städte der Nationen fielen, und der großen <Stadt> Babylon* wurde vor Gott gedacht*, ihr den Kelch des Weines des Grimmes seines Zornes zu geben*.", footnotes: ["℘ Kap. 11,8", "vielleicht verschlüsselte Bezeichnung für Rom\n℘ Kap. 14,8", "℘ Kap. 18,5", "℘ Kap. 14,10"] },
      { number: 20, text: "Und jede Insel verschwand, und Berge wurden nicht gefunden*.", footnotes: ["℘ Kap. 6,14; 20,11"] },
      { number: 21, text: "Und ein großer Hagel, wie zentnerschwer, fällt aus dem Himmel auf die Menschen nieder*; und die Menschen lästerten Gott wegen der Plage des Hagels, denn seine Plage ist sehr groß.", footnotes: ["℘ Kap. 8,7; Jos 10,11"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und es kam einer von den sieben Engeln, welche die sieben Schalen hatten*, und redete mit mir und sprach: Komm her! Ich will dir das Gericht über die große Hure zeigen, die an vielen Wassern sitzt*,", heading: "Das große Babylon und das Tier", footnotes: ["℘ Kap. 15,7", "℘ Jer 51,13"] },
      { number: 2, text: "mit der die Könige der Erde Unzucht* getrieben haben*; und die Bewohner der Erde sind trunken geworden von dem Wein ihrer Unzucht*.", footnotes: ["o. Hurerei", "℘ Kap. 18,3.9; Jes 23,17", "o. Hurerei\n℘ Kap. 14,8"] },
      { number: 3, text: "Und er führte mich im Geist hinweg in eine Wüste; und ich sah eine Frau auf einem scharlachroten Tier sitzen, das voller Lästernamen war und sieben Köpfe und zehn Hörner hatte*.", footnotes: ["℘ Kap. 12,3"] },
      { number: 4, text: "Und die Frau war bekleidet mit Purpur und Scharlach und übergoldet mit Gold und Edelgestein und Perlen*, und sie hatte einen goldenen Becher in ihrer Hand, voller Gräuel und Unreinheit ihrer Unzucht*;", footnotes: ["℘ Kap. 18,16", "o. Hurerei\n℘ Jer 51,7"] },
      { number: 5, text: "und sie hatte an ihrer Stirn einen Namen geschrieben, ein Geheimnis: Babylon*, die Große*, die Mutter der Huren und der Gräuel der Erde.", footnotes: ["vielleicht verschlüsselte Bezeichnung für Rom", "℘ Kap. 14,8"] },
      { number: 6, text: "Und ich sah die Frau trunken vom Blut der Heiligen und vom Blut der Zeugen Jesu*. Und ich wunderte mich, als ich sie sah, mit großer Verwunderung.", footnotes: ["℘ Kap. 16,6"] },
      { number: 7, text: "Und der Engel sprach zu mir: Warum wundertest du dich? Ich will dir das Geheimnis der Frau sagen und des Tieres, das sie trägt und die sieben Köpfe und die zehn Hörner hat*.", footnotes: ["℘ Kap. 13,1"] },
      { number: 8, text: "Das Tier, das du gesehen hast, war und ist nicht und wird aus dem Abgrund heraufsteigen* und geht ins Verderben*; und die Bewohner der Erde, deren Namen nicht im Buch des Lebens geschrieben sind* von Grundlegung der Welt an, werden sich wundern, wenn sie das Tier sehen*, dass es war und nicht ist und da sein wird.", footnotes: ["℘ Kap. 11,7", "℘ Kap. 19,20", "℘ Kap. 3,5.10", "℘ Kap. 13,3"] },
      { number: 9, text: "Hier ist der Verstand <nötig>, der Weisheit hat*: Die sieben Köpfe sind sieben Berge, auf denen die Frau sitzt. Und es sind sieben Könige*:", footnotes: ["℘ Kap. 13,18", "℘ Kap. 13,1"] },
      { number: 10, text: "Die fünf <ersten> sind gefallen, der eine ist, der andere ist noch nicht gekommen; und wenn er kommt, muss er eine kurze Zeit bleiben." },
      { number: 11, text: "Und das Tier, das war und nicht ist, es ist selbst sowohl ein achter als auch von den sieben und geht ins Verderben*.", footnotes: ["℘ Kap. 19,20"] },
      { number: 12, text: "Und die zehn Hörner, die du gesehen hast, sind zehn Könige*, die noch kein Königreich* empfangen haben, aber mit dem Tier eine Stunde* Macht* wie Könige empfangen.", footnotes: ["℘ Dan 7,20.24", "o. keine Königsherrschaft", "d. h. für ganz kurze Zeit", "o. Vollmacht"] },
      { number: 13, text: "Diese haben einen Sinn und geben ihre Kraft und Macht* dem Tier.", footnotes: ["o. Vollmacht"] },
      { number: 14, text: "Diese werden mit dem Lamm Krieg führen*, und das Lamm wird sie überwinden; denn es ist Herr der Herren* und König der Könige*, und die mit ihm <sind, sind>* Berufene* und Auserwählte* und Treue*.", footnotes: ["℘ Kap. 16,14", "℘ Apg 10,36", "℘ Kap. 19,16; 1Tim 6,15", "℘ 1Thes 4,14", "℘ Hebr 3,1", "℘ Röm 11,7", "℘ Eph 1,1"] },
      { number: 15, text: "Und er spricht zu mir: Die Wasser, die du gesehen hast, wo die Hure sitzt, sind Völker und Völkerscharen* und Nationen und Sprachen*;", footnotes: ["o. Volksmengen", "℘ Jes 8,7; Jer 47,2"] },
      { number: 16, text: "und die zehn Hörner, die du gesehen hast, und das Tier, diese werden die Hure hassen und werden sie verwüsten und nackt machen und werden ihr Fleisch fressen und sie mit Feuer verbrennen*.", footnotes: ["℘ Kap. 18,8; Hes 16,40.41"] },
      { number: 17, text: "Denn Gott hat in ihre Herzen gegeben, seinen* Sinn zu tun und in einem Sinn zu handeln* und ihr Königreich* dem Tier zu geben, bis die Worte Gottes vollendet sein werden.", footnotes: ["d. h. des Tieres", "w. einen Sinn zu tun", "o. ihre Königsherrschaft"] },
      { number: 18, text: "Und die Frau, die du gesehen hast, ist die große Stadt, welche die Königsherrschaft über die Könige der Erde hat*.", footnotes: ["℘ Kap. 18,10"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Nach diesem sah ich einen anderen Engel aus dem Himmel herabkommen, der große Macht* hatte; und die Erde wurde von seiner Herrlichkeit erleuchtet*.", heading: "Der Untergang Babylons", footnotes: ["o. Vollmacht", "℘ Kap. 5,2"] },
      { number: 2, text: "Und er rief mit starker Stimme und sprach: Gefallen, gefallen ist Babylon*, die Große*, und ist eine Behausung von Dämonen geworden und ein Gefängnis jedes unreinen Geistes und ein Gefängnis jedes unreinen und gehassten Vogels*.", footnotes: ["vielleicht verschlüsselte Bezeichnung für Rom", "℘ Kap. 14,8", "mit anderen Handschr.: ein Gefängnis jedes unreinen Geistes, und ein Gefängnis jedes unreinen Vogels und ein Gefängnis jedes unreinen und gehassten Tieres\n℘ Jes 13,21; 34,14; Jer 50,39"] },
      { number: 3, text: "Denn von dem Wein der Wut ihrer Unzucht* haben alle Nationen getrunken*, und die Könige der Erde haben Unzucht* mit ihr getrieben*, und die Kaufleute der Erde sind durch die Kraft* ihrer Üppigkeit reich geworden*.", footnotes: ["o. Hurerei; so auch V. 9", "℘ Kap. 14,8", "o. Hurerei; so auch V. 9", "℘ Kap. 17,2; Nah 3,4", "o. Macht", "℘ V. 11"] },
      { number: 4, text: "Und ich hörte eine andere Stimme aus dem Himmel sagen: Geht aus ihr hinaus, mein Volk, damit ihr nicht an ihren Sünden teilhabt* und damit ihr nicht von ihren Plagen empfangt*!", footnotes: ["℘ 2Kor 6,17; 1Tim 5,22", "℘ Jes 48,20; 52,11; Jer 50,8; 51,6.45"] },
      { number: 5, text: "Denn ihre Sünden sind aufgehäuft bis zum Himmel*, und Gott hat ihrer Ungerechtigkeiten gedacht*.", footnotes: ["℘ 1Mo 18,20.21; Jer 51,9", "℘ Kap. 16,19"] },
      { number: 6, text: "Vergeltet ihr, wie auch sie vergolten hat*, und verdoppelt <es ihr> doppelt nach ihren Werken*; mischt ihr den Kelch, den sie gemischt hat, doppelt!", footnotes: ["℘ 2Thes 1,6", "℘ Ps 137,8; Jer 50,29"] },
      { number: 7, text: "Wie viel sie sich verherrlicht hat und üppig gewesen ist, so viel Qual und Trauer gebt ihr! Denn sie spricht in ihrem Herzen: Ich sitze als Königin, und Witwe bin ich nicht, und Traurigkeit werde ich nicht sehen*.", footnotes: ["℘ Jes 47,8"] },
      { number: 8, text: "Darum werden ihre Plagen an einem Tag kommen*: Tod und Trauer und Hunger, und mit Feuer wird sie verbrannt werden*; denn stark ist der Herr, Gott, der sie gerichtet hat*.", footnotes: ["℘ Jes 47,9", "℘ Kap. 17,16", "℘ Jer 50,34"] },
      { number: 9, text: "Und es werden um sie weinen und wehklagen die Könige der Erde, die mit ihr Unzucht getrieben haben* und üppig gewesen sind, wenn sie den Rauch ihres Brandes sehen;", footnotes: ["℘ Kap. 17,2; Nah 3,4"] },
      { number: 10, text: "und sie werden aus Furcht vor ihrer Qual* weitab stehen und sagen: Wehe, wehe! Die große Stadt, Babylon, die starke Stadt*! Denn in einer Stunde* ist dein Gericht gekommen.", footnotes: ["℘ Hes 26,16.17", "℘ Kap. 14,8; 17,18", "d. h. in ganz kurzer Zeit"] },
      { number: 11, text: "Und die Kaufleute der Erde weinen und trauern um sie, weil niemand mehr ihre Ware* kauft*:", footnotes: ["w. Ladung, Fracht", "℘ V. 3; Hes 27,36"] },
      { number: 12, text: "Ware von Gold und Silber und Edelgestein und Perlen und feiner Leinwand und Purpur und Seide und Scharlachstoff und alles Thujaholz und jedes Gerät von Elfenbein und jedes Gerät von kostbarstem Holz und von Erz und Eisen und Marmor" },
      { number: 13, text: "und Zimt und Haarbalsam und Räucherwerk und Salböl und Weihrauch und Wein und Öl und Feinmehl und Weizen und Rinder und Schafe und von Pferden und von Wagen und von Leibeigenen* und Menschenseelen*.", footnotes: ["w. Leibern; so wurden auch Sklaven bezeichnet", "℘ Hes 27,12.13"] },
      { number: 14, text: "Und die Früchte, nach denen deine Seele begehrte, sind* von dir gewichen, und alle Pracht und Glanz sind dir verloren*, und man wird sie nie mehr finden.", footnotes: ["w. Und dein Obst der Begierde der Seele ist", "o. vernichtet"] },
      { number: 15, text: "Die Kaufleute dieser Dinge, die an ihr reich geworden sind, werden aus Furcht vor ihrer Qual weitab stehen, weinend und trauernd," },
      { number: 16, text: "und werden sagen: Wehe, wehe! Die große Stadt, die bekleidet war mit feiner Leinwand und Purpur und Scharlachstoff und übergoldet mit Gold und Edelgestein und Perlen*!", footnotes: ["℘ Kap. 17,4"] },
      { number: 17, text: "Denn in einer Stunde* ist der so große Reichtum verwüstet worden. Und jeder Steuermann und jeder Küstenfahrer und Schiffsleute und alle, die auf dem Meere beschäftigt sind, standen weitab*", footnotes: ["d. h. in ganz kurzer Zeit", "℘ Jes 23,14"] },
      { number: 18, text: "und riefen, als sie den Rauch ihres Brandes sahen, und sprachen: Wer war der großen Stadt gleich?" },
      { number: 19, text: "Und sie warfen Staub auf ihre Häupter* und riefen weinend und trauernd und sprachen: Wehe, wehe! Die große Stadt, in der alle, die Schiffe auf dem Meere hatten, reich wurden von ihrer Kostbarkeit! Denn in einer Stunde* ist sie verwüstet worden*.", footnotes: ["℘ Hes 27,30", "d. h. in ganz kurzer Zeit", "℘ Hes 26,19"] },
      { number: 20, text: "Sei fröhlich über sie, du Himmel*, und ihr Heiligen und Apostel und Propheten! Denn Gott hat für euch das Urteil* an ihr vollzogen.", footnotes: ["℘ Kap. 12,12; Jer 51,48", "o. Gericht"] },
      { number: 21, text: "Und ein starker Engel hob einen Stein auf wie einen großen Mühlstein und warf ihn ins Meer und sprach: So wird Babylon, die große Stadt, mit Gewalt niedergeworfen und nie mehr gefunden werden*.", footnotes: ["℘ Jer 51,63.64"] },
      { number: 22, text: "Und die Stimme der Harfensänger und Musiker und Flötenspieler und Trompeter wird nie mehr in dir gehört* und nie mehr ein Künstler irgendeiner Kunst in dir gefunden und das Geräusch des Mühlsteins nie mehr in dir gehört werden,", footnotes: ["℘ Jes 24,8; Hes 26,13"] },
      { number: 23, text: "und das Licht einer Lampe wird nie mehr in dir scheinen und die Stimme von Bräutigam und Braut nie mehr in dir gehört werden*; denn deine Kaufleute waren die Großen der Erde; denn durch deine Zauberei sind alle Nationen verführt worden*.", footnotes: ["℘ Jer 7,34; 16,9; 25,10", "℘ Jes 47,9"] },
      { number: 24, text: "Und in ihr wurde das Blut von Propheten und Heiligen gefunden und von allen denen, die auf der Erde hingeschlachtet worden sind*.", footnotes: ["℘ Kap. 16,6"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Nach diesem hörte ich <etwas> wie eine laute Stimme einer großen Volksmenge im Himmel, die sprachen: Halleluja*! Das Heil und die Herrlichkeit und die Macht <sind> unseres Gottes*!", heading: "Jubel im Himmel über den Untergang Babylons", footnotes: ["d. h. Lobet den Herrn", "℘ Kap. 7,10.12; 11,15"] },
      { number: 2, text: "Denn wahrhaftig und gerecht sind seine Gerichte*; denn er hat die große Hure gerichtet, welche die Erde mit ihrer Unzucht* verdarb*, und er hat das Blut seiner Knechte* an ihr* gerächt*.", footnotes: ["℘ Kap. 15,3; Ps 119,137; Röm 2,2", "o. Hurerei", "℘ Kap. 11,18", "w. Sklaven", "w. an ihrer Hand", "℘ Kap. 6,10; 2Kö 9,7"] },
      { number: 3, text: "Und zum zweiten Mal sprachen sie: Halleluja! Und ihr Rauch steigt auf von Ewigkeit zu Ewigkeit*.", footnotes: ["w. in die Zeitalter der Zeitalter (griech. Äonen)\n℘ Kap. 14,11; Jes 34,10"] },
      { number: 4, text: "Und die vierundzwanzig Ältesten und die vier lebendigen Wesen fielen nieder und beteten Gott an*, der auf dem Thron sitzt*, und sagten: Amen*, Halleluja!", footnotes: ["℘ Kap. 4,10", "℘ Kap. 4,2", "Beteuerungsformel für die Wahrhaftigkeit des Gesagten; in den Evangelien am Anfang feierlicher Erklärungen Jesu mit »Wahrlich!« übersetzt; vgl. Kap. 22,20\n℘ Kap. 5,14"] },
      { number: 5, text: "Und eine Stimme kam vom Thron her, die sprach: Lobt unseren Gott, alle seine Knechte*, die ihr ihn fürchtet*, die Kleinen* und die Großen*!", footnotes: ["w. Sklaven\n℘ Ps 135,1", "℘ Ps 22,24", "d. h. die Geringen", "℘ Kap. 11,18"] },
      { number: 6, text: "Und ich hörte <etwas> wie eine Stimme einer großen Volksmenge und wie ein Rauschen vieler Wasser* und wie ein Rollen starker Donner*, die sprachen: Halleluja*! Denn der Herr, unser Gott, der Allmächtige, hat die Herrschaft angetreten*.", heading: "Das Hochzeitsmahl des Lammes", footnotes: ["℘ Kap. 1,15", "℘ Kap. 14,2", "d. h. Lobet den Herrn", "℘ Kap. 11,17"] },
      { number: 7, text: "Lasst uns fröhlich sein und jubeln und ihm die Ehre geben*; denn die Hochzeit des Lammes ist gekommen*, und seine Frau hat sich bereitgemacht*.", footnotes: ["℘ Ps 118,24", "℘ Mt 22,2; 25,10", "℘ Kap. 21,9"] },
      { number: 8, text: "Und ihr wurde gegeben, dass sie sich kleide in feine Leinwand, glänzend, rein*; denn die feine Leinwand sind die gerechten Taten der Heiligen*.", footnotes: ["℘ Kap. 3,5", "℘ Ps 132,9; Jes 61,10"] },
      { number: 9, text: "Und er spricht zu mir: Schreibe: Glückselig, die eingeladen sind zum Hochzeitsmahl des Lammes! Und er spricht zu mir: Dies sind die wahrhaftigen Worte Gottes*.", footnotes: ["℘ Kap. 21,5; 22,6; 1Tim 1,15"] },
      { number: 10, text: "Und ich fiel zu seinen Füßen nieder, ihn anzubeten. Und er spricht zu mir: Siehe zu, <tu es> nicht! Ich bin dein Mitknecht* und der deiner Brüder, die das Zeugnis Jesu haben. Bete Gott an*! Denn das Zeugnis Jesu ist der Geist der Weissagung*.", footnotes: ["w. Mitsklave", "℘ Kap. 22,8.9; Lk 4,8; Apg 10,26", "℘ Kap. 1,2"] },
      { number: 11, text: "Und ich sah den Himmel geöffnet*, und siehe, ein weißes Pferd*, und der darauf saß, heißt Treu und Wahrhaftig*, und er richtet und führt Krieg in Gerechtigkeit*.", heading: "Christus besiegt das Tier und sein Heer", footnotes: ["℘ Kap. 4,1; 6,2", "℘ Jes 47,9", "℘ Kap. 3,14", "℘ Ps 45,5; 96,13; Jes 11,4.5"] },
      { number: 12, text: "Seine Augen aber sind eine Feuerflamme*, und auf seinem Haupt sind viele Diademe*, und er trägt einen Namen geschrieben, den niemand kennt als nur er selbst;", footnotes: ["℘ Kap. 1,14", "Das Diadem, ein Stirnreif, war im Altertum das Zeichen der Königswürde."] },
      { number: 13, text: "und er ist bekleidet mit einem in Blut getauchten Gewand*, und sein Name heißt: Das Wort Gottes*.", footnotes: ["℘ Jes 63,1-3", "℘ Joh 1,1"] },
      { number: 14, text: "Und die Truppen, die im Himmel sind, folgten ihm auf weißen Pferden, bekleidet mit weißer, reiner Leinwand*.", footnotes: ["℘ Jud 14"] },
      { number: 15, text: "Und aus seinem Mund geht ein scharfes Schwert hervor*, damit er mit ihm die Nationen schlage; und er wird sie hüten mit eisernem Stab*, und er tritt die Kelter des Weines des Grimmes des Zornes Gottes, des Allmächtigen*.", footnotes: ["℘ Kap. 1,16", "℘ Kap. 2,27; Jes 11,4", "℘ Kap. 14,19.20; Ps 24,8"] },
      { number: 16, text: "Und er trägt auf seinem Gewand und an seiner Hüfte einen Namen geschrieben: König der Könige und Herr der Herren*.", footnotes: ["℘ Kap. 1,5; 17,14; Mt 24,30"] },
      { number: 17, text: "Und ich sah einen Engel in der Sonne stehen, und er rief mit lauter Stimme und sprach zu allen Vögeln, die hoch oben am Himmel fliegen: Kommt her, versammelt euch zum großen Mahl* Gottes*,", footnotes: ["o. Gastmahl; o. Abendessen", "℘ Hes 39,4"] },
      { number: 18, text: "damit ihr Fleisch von Königen fresst und Fleisch von Obersten* und Fleisch von Mächtigen und Fleisch von Pferden und von denen, die darauf sitzen, und Fleisch von allen, sowohl von Freien als auch Sklaven, sowohl von Kleinen* als auch Großen*!", footnotes: ["griech. Chiliarchen; d. h. Tausendschaftsführer", "d. h. Geringen", "℘ Hes 39,17-20"] },
      { number: 19, text: "Und ich sah das Tier und die Könige der Erde und ihre Truppen versammelt, um mit dem, der auf dem Pferd saß, und mit seinen Truppen Krieg zu führen*.", footnotes: ["℘ Kap. 16,14; Ps 2,2"] },
      { number: 20, text: "Und es wurde ergriffen das Tier* und der falsche Prophet* — der mit ihm war und die Zeichen vor ihm tat*, durch die er die verführte, die das Malzeichen des Tieres annahmen und sein Bild anbeteten* —, lebendig wurden die zwei in den Feuersee geworfen, der mit Schwefel brennt*.", footnotes: ["℘ Kap. 13,1.2", "℘ Kap. 16,13", "℘ Kap. 13,14", "℘ Kap. 13,16", "℘ Kap. 14,10; 20,14; 21,8; Jes 30,33; Dan 7,11"] },
      { number: 21, text: "Und die Übrigen wurden getötet mit dem Schwert, das aus dem Mund dessen hervorging*, der auf dem Pferd saß; und alle Vögel wurden von ihrem Fleisch gesättigt.", footnotes: ["℘ Kap. 1,16"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und ich sah einen Engel aus dem Himmel herabkommen, der den Schlüssel des Abgrundes* und eine große Kette in seiner Hand hatte.", heading: "Bindung Satans — Tausendjähriges Reich", footnotes: ["℘ Lk 8,31"] },
      { number: 2, text: "Und er griff* den Drachen, die alte Schlange, die der Teufel und der Satan ist*; und er band ihn tausend Jahre", footnotes: ["o. nahm gefangen", "℘ Kap. 12,9"] },
      { number: 3, text: "und warf ihn in den Abgrund* und schloss zu und versiegelte über ihm, damit er nicht mehr die Nationen verführe*, bis die tausend Jahre vollendet sind. Nach diesem muss er für kurze Zeit losgelassen werden*.", footnotes: ["℘ Kap. 9,1", "℘ Kap. 12,9; 2Thes 2,9.10", "℘ V. 7.8"] },
      { number: 4, text: "Und ich sah Throne*, und sie setzten sich darauf, und das Gericht wurde ihnen übergeben*; und <ich sah> die Seelen derer, die um des Zeugnisses Jesu* und um des Wortes Gottes willen enthauptet worden waren*, und die, welche das Tier und sein Bild nicht angebetet und das Malzeichen nicht an ihre Stirn und an ihre Hand angenommen hatten*, und sie wurden lebendig* und herrschten mit dem Christus tausend Jahre*.", footnotes: ["℘ Dan 7,9", "℘ Dan 7,22; Lk 22,30; 1Kor 6,2", "℘ Kap. 1,2", "℘ Kap. 6,9", "℘ Kap. 13,16", "w. lebten", "℘ Kap. 5,10"] },
      { number: 5, text: "Die Übrigen der Toten wurden nicht lebendig*, bis die tausend Jahre vollendet waren. Dies ist die erste Auferstehung*.", footnotes: ["w. lebten nicht", "℘ 1Kor 15,23"] },
      { number: 6, text: "Glückselig und heilig, wer teilhat an der ersten Auferstehung! Über diese hat der zweite Tod* keine Macht*, sondern sie werden Priester Gottes und des Christus sein* und mit ihm herrschen die tausend Jahre.", footnotes: ["℘ Kap. 2,11", "o. Vollmacht\n℘ Joh 5,29", "℘ Kap. 1,6"] },
      { number: 7, text: "Und wenn die tausend Jahre vollendet sind, wird der Satan aus seinem Gefängnis losgelassen werden", heading: "Letzter Aufstand Satans und endgültiges Gericht über ihn" },
      { number: 8, text: "und wird hinausgehen, die Nationen zu verführen*, die an den vier Ecken der Erde* sind, den Gog und den Magog, um sie zum Krieg zu versammeln; deren Zahl ist wie der Sand des Meeres*.", footnotes: ["℘ V. 3", "℘ Kap. 7,1", "℘ Jos 11,4; Hes 38,2.9.15"] },
      { number: 9, text: "Und sie zogen herauf auf die Breite der Erde und umzingelten das Heerlager der Heiligen* und die geliebte Stadt*; und Feuer kam aus dem Himmel herab und verschlang sie*.", footnotes: ["℘ Dan 7,21", "℘ Ps 87,2; Jer 12,7", "℘ 2Kö 1,10.12; Hes 38,22; 39,6; Sach 12,9; 14,3"] },
      { number: 10, text: "Und der Teufel, der sie verführte, wurde in den Feuer- und Schwefelsee geworfen, wo sowohl das Tier als auch der falsche Prophet sind*; und sie werden Tag und Nacht gepeinigt werden von Ewigkeit zu Ewigkeit*.", footnotes: ["℘ Kap. 16,13", "w. in die Zeitalter der Zeitalter\n℘ Kap. 14,10.11"] },
      { number: 11, text: "Und ich sah einen großen weißen Thron und den, der darauf saß*, vor dessen Angesicht die Erde entfloh* und der Himmel*, und keine Stätte wurde für sie gefunden*.", heading: "Zweite Auferstehung und Weltgericht", footnotes: ["o. sitzt\n℘ Kap. 4,2", "℘ Ps 114,3", "℘ Kap. 16,20; 21,1; Jes 51,6; 2Petr 3,10", "℘ Kap. 12,8"] },
      { number: 12, text: "Und ich sah die Toten, die Großen und die Kleinen*, vor dem Thron stehen, und Bücher wurden geöffnet*; und ein anderes Buch wurde geöffnet, welches das des Lebens ist*. Und die Toten wurden gerichtet nach dem, was in den Büchern geschrieben war, nach ihren Werken*.", footnotes: ["d. h. die Geringen", "℘ Dan 7,10", "℘ Kap. 3,5", "℘ Kap. 2,23; Spr 24,12; Pred 12,14; 2Tim 4,1; 1Petr 1,17"] },
      { number: 13, text: "Und das Meer gab die Toten, die in ihm waren, und der Tod und der Hades* gaben die Toten, die in ihnen waren*, und sie wurden gerichtet, ein jeder nach seinen Werken*.", footnotes: ["d. i. das Totenreich", "℘ Lk 20,38; Apg 24,15", "℘ Kap. 2,23; Spr 24,12; Pred 12,14; 2Tim 4,1; 1Petr 1,17"] },
      { number: 14, text: "Und der Tod und der Hades wurden in den Feuersee geworfen*. Dies ist der zweite Tod*, der Feuersee*.", footnotes: ["℘ 1Kor 15,26", "℘ Kap. 2,11", "o. Dieser zweite Tod ist der Feuersee"] },
      { number: 15, text: "Und wenn jemand nicht geschrieben gefunden wurde in dem Buch des Lebens*, so wurde er in den Feuersee geworfen*.", footnotes: ["℘ Kap. 3,5", "℘ Kap. 19,20; Mt 25,41"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Und ich sah einen neuen Himmel und eine neue Erde*; denn der erste Himmel und die erste Erde waren vergangen*, und das Meer ist nicht mehr.", heading: "Das neue Jerusalem", footnotes: ["℘ Jes 65,17; 66,22; 2Petr 3,13", "℘ Kap. 20,11"] },
      { number: 2, text: "Und ich sah die heilige Stadt*, das neue Jerusalem*, aus dem Himmel von Gott herabkommen, bereitet wie eine für ihren Mann geschmückte Braut*.", footnotes: ["℘ Kap. 11,2; Jes 52,1", "℘ V. 10; Kap. 3,12", "℘ Jes 61,10"] },
      { number: 3, text: "Und ich hörte eine laute Stimme vom Thron her sagen: Siehe, das Zelt Gottes bei den Menschen! Und er wird bei ihnen wohnen*, und sie werden sein Volk* sein, und Gott selbst wird bei ihnen sein, ihr Gott*.", footnotes: ["o. zelten\n℘ Kap. 7,15; Hes 43,7; 48,35", "w. seine Völker", "℘ 2Mo 29,45; Hes 37,27"] },
      { number: 4, text: "Und er wird jede Träne von ihren Augen abwischen*, und der Tod wird nicht mehr sein*, noch Trauer noch Geschrei noch Schmerz wird mehr sein*; denn das Erste ist vergangen.", footnotes: ["℘ Kap. 7,17", "℘ Kap. 20,14; Jes 65,16.19; Lk 20,36", "℘ Jes 35,10; 51,11"] },
      { number: 5, text: "Und der, welcher auf dem Thron saß*, sprach: Siehe, ich mache alles neu*. Und er spricht: Schreibe! Denn diese Worte sind gewiss* und wahrhaftig*.", footnotes: ["℘ Kap. 4,2", "℘ Jes 43,19; 2Kor 5,17", "o. zuverlässig; o. treu", "℘ Kap. 19,9"] },
      { number: 6, text: "Und er sprach zu mir: Es ist geschehen*. Ich bin das Alpha und das Omega*, der Anfang* und das Ende*. Ich will dem Dürstenden aus der Quelle des Wassers des Lebens geben umsonst*.", footnotes: ["℘ Kap. 16,17", "Alpha und Omega (A und O) sind der erste und der letzte Buchstabe des griech. Alphabets.\n℘ Kap. 1,8", "o. Ursprung", "o. Ziel", "℘ Kap. 22,17; Jes 55,1; Joh 4,14"] },
      { number: 7, text: "Wer überwindet*, wird dies erben, und ich werde ihm Gott sein*, und er wird mir Sohn sein*.", footnotes: ["℘ Kap. 2,7", "℘ Sach 8,8", "℘ 2Sam 7,14; 2Kor 6,18"] },
      { number: 8, text: "Aber den Feigen und Ungläubigen* und mit Gräueln Befleckten und Mördern und Unzüchtigen* und Zauberern und Götzendienern* und allen Lügnern* ist ihr Teil in dem See, der mit Feuer und Schwefel brennt; das ist der zweite Tod*.", footnotes: ["o. Treulosen\n℘ Joh 3,36", "o. Hurern", "℘ 1Kor 6,9", "℘ Kap. 22,15; Spr 19,9; Mt 15,19", "℘ Kap. 19,20; 20,14.15"] },
      { number: 9, text: "Und es kam einer von den sieben Engeln, welche die sieben Schalen hatten*, voll der sieben letzten Plagen, und redete mit mir und sprach: Komm her! Ich will dir die Braut*, die Frau des Lammes, zeigen*.", footnotes: ["℘ Kap. 15,1.7", "℘ Kap. 22,17", "℘ Kap. 19,7"] },
      { number: 10, text: "Und er führte mich im Geist hinweg* auf einen großen und hohen Berg* und zeigte mir die heilige Stadt Jerusalem, wie sie aus dem Himmel von Gott herabkam*,", footnotes: ["℘ Kap. 1,10", "℘ Kap. 17,1", "℘ V. 2; Hes 40,2"] },
      { number: 11, text: "und sie hatte die Herrlichkeit Gottes*. Ihr Lichtglanz war gleich einem sehr kostbaren Edelstein, wie ein kristallheller Jaspisstein*;", footnotes: ["℘ V. 23", "℘ Kap. 4,3"] },
      { number: 12, text: "und sie hatte eine große und hohe Mauer* und hatte zwölf Tore und an den Toren zwölf Engel und Namen darauf geschrieben, welche die Namen der zwölf Stämme der Söhne Israels sind*:", footnotes: ["℘ Sach 2,9", "℘ 2Mo 28,21"] },
      { number: 13, text: "nach Osten* drei Tore und nach Norden drei Tore und nach Süden drei Tore und nach Westen drei Tore*.", footnotes: ["w. Von . . . her; so weiter in V. 13", "℘ Hes 48,31-34"] },
      { number: 14, text: "Und die Mauer der Stadt hatte zwölf Grundsteine* und auf ihnen zwölf Namen der zwölf Apostel des Lammes*.", footnotes: ["℘ Hebr 11,10", "℘ Eph 2,20"] },
      { number: 15, text: "Und der mit mir redete, hatte ein Maß, ein goldenes Rohr*, um die Stadt und ihre Tore und ihre Mauer zu messen*.", footnotes: ["℘ Kap. 11,1", "℘ Hes 40,3.5; Sach 2,5.6"] },
      { number: 16, text: "Und die Stadt ist viereckig angelegt, und ihre Länge ist so groß wie die Breite. Und er maß die Stadt mit dem Rohr auf 12 000 Stadien; ihre Länge und Breite und Höhe sind gleich." },
      { number: 17, text: "Und er maß ihre Mauer, 144 Ellen, eines Menschen Maß, das ist eines Engels <Maß>*.", footnotes: ["℘ Hes 48,16.17"] },
      { number: 18, text: "Und der Baustoff* ihrer Mauer war Jaspis und die Stadt reines Gold, gleich reinem Glas.", footnotes: ["w. das Hineingebaute"] },
      { number: 19, text: "Die Grundsteine der Mauer der Stadt waren mit jeder <Art> Edelstein* geschmückt: der erste Grundstein ein Jaspis; der zweite ein Saphir; der dritte ein Chalzedon; der vierte ein Smaragd;", footnotes: ["℘ 2Mo 28,17-20; Jes 54,11.12"] },
      { number: 20, text: "der fünfte ein Sardonyx; der sechste ein Sarder; der siebente ein Chrysolith; der achte ein Beryll; der neunte ein Topas; der zehnte ein Chrysopras; der elfte ein Hyazinth; der zwölfte ein Amethyst." },
      { number: 21, text: "Und die zwölf Tore waren zwölf Perlen, je eines der Tore war aus einer Perle, und die Straße der Stadt* reines Gold, wie durchsichtiges Glas.", footnotes: ["℘ Kap. 22,2"] },
      { number: 22, text: "Und ich sah keinen Tempel in ihr, denn der Herr, Gott, der Allmächtige, ist ihr Tempel, und das Lamm." },
      { number: 23, text: "Und die Stadt bedarf nicht der Sonne noch des Mondes, damit sie ihr scheinen; denn die Herrlichkeit Gottes hat sie erleuchtet*, und ihre Lampe ist das Lamm*.", footnotes: ["℘ V. 11; Ps 84,12; Jes 60,19", "℘ Kap. 22,5"] },
      { number: 24, text: "Und die Nationen werden in* ihrem* Licht wandeln*, und die Könige der Erde bringen ihre Herrlichkeit zu ihr*.", footnotes: ["w. durch ihr Licht", "d. h. dem der Herrlichkeit Gottes", "℘ Ps 89,16", "℘ Jes 60,3.5"] },
      { number: 25, text: "Und ihre Tore werden bei Tag nicht geschlossen werden*, denn Nacht wird dort nicht sein*.", footnotes: ["℘ Jes 60,11", "℘ Kap. 22,5"] },
      { number: 26, text: "Und man wird die Herrlichkeit und die Ehre der Nationen zu ihr bringen*.", footnotes: ["℘ Jes 66,12"] },
      { number: 27, text: "Und alles Unreine* wird nicht in sie hineinkommen, noch <derjenige>, der Gräuel und Lüge tut, sondern nur die, welche geschrieben sind im Buch des Lebens des Lammes*.", footnotes: ["o. Gemeine; d. h. kultisch Unreine\n℘ Kap. 22,14; Jes 52,1; Sach 14,21", "℘ Kap. 3,5"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Und er zeigte mir einen Strom von Wasser des Lebens, glänzend wie Kristall, der hervorging aus dem Thron Gottes und des Lammes*.", footnotes: ["℘ Ps 36,10; 46,5; Hes 47,1; Joe 4,18; Sach 14,8"] },
      { number: 2, text: "In der Mitte ihrer* Straße* und des Stromes, diesseits und jenseits, <war der> Baum* des Lebens*, der zwölf<mal> Früchte trägt und jeden Monat seine Frucht gibt; und die Blätter des Baumes <sind> zur Heilung der Nationen*.", footnotes: ["d. h. der Stadt", "℘ Kap. 21,21", "w. Holz", "℘ Kap. 2,7", "℘ Jer 3,17; Hes 47,12"] },
      { number: 3, text: "Und keinerlei Fluch wird mehr sein*; und der Thron Gottes und des Lammes wird in ihr sein*; und seine Knechte* werden ihm dienen*,", footnotes: ["℘ Sach 14,11", "℘ Ps 46,6; Hes 48,35", "w. Sklaven", "℘ Kap. 7,15"] },
      { number: 4, text: "und sie werden sein Angesicht sehen*; und sein Name wird an ihren Stirnen sein*.", footnotes: ["℘ Jes 33,17; Mt 5,8; 1Kor 13,12", "℘ Kap. 3,12"] },
      { number: 5, text: "Und Nacht wird nicht mehr sein*, und sie bedürfen nicht des Lichtes einer Lampe und des Lichtes der Sonne; denn der Herr, Gott, wird über ihnen leuchten*, und sie werden herrschen von Ewigkeit zu Ewigkeit*.", footnotes: ["℘ Kap. 21,25", "℘ Kap. 21,23; Jes 60,1", "w. in die Zeitalter der Zeitalter (griech. Äonen)\n℘ Kap. 5,10; Dan 7,18.27"] },
      { number: 6, text: "Und er sprach zu mir: Diese Worte sind gewiss* und wahrhaftig*, und der Herr, der Gott der Geister der Propheten*, hat seinen Engel gesandt, seinen Knechten* zu zeigen, was bald* geschehen muss*.", heading: "Schlussermahnungen und Hinweis auf das baldige Kommen Jesu", footnotes: ["o. zuverlässig; o. treu", "℘ Kap. 19,9", "℘ 4Mo 27,16; 1Kor 14,32", "w. Sklaven", "o. in Kürze", "℘ Kap. 1,1"] },
      { number: 7, text: "Und siehe, ich komme bald*. Glückselig, der die Worte der Weissagung dieses Buches bewahrt*!", footnotes: ["w. schnell; so auch V. 12.20\n℘ Kap. 3,11; Joh 14,3", "℘ Kap. 1,3"] },
      { number: 8, text: "Und ich, Johannes, bin der, welcher diese Dinge hörte und sah; und als ich <sie> hörte und sah, fiel ich nieder, um anzubeten vor den Füßen des Engels, der mir diese Dinge zeigte." },
      { number: 9, text: "Und er spricht zu mir: Siehe zu, <tu es> nicht! Ich bin dein Mitknecht* und der deiner Brüder, der Propheten, und derer, welche die Worte dieses Buches bewahren. Bete Gott an*!", footnotes: ["w. Mitsklave", "℘ Kap. 19,10"] },
      { number: 10, text: "Und er spricht zu mir: Versiegle nicht die Worte der Weissagung dieses Buches*! Denn die Zeit ist nahe*.", footnotes: ["℘ Kap. 10,4", "℘ Kap. 1,3"] },
      { number: 11, text: "Wer Unrecht tut, tue noch Unrecht, und der Unreine verunreinige sich noch, und der Gerechte übe noch Gerechtigkeit, und der Heilige heilige sich noch!" },
      { number: 12, text: "Siehe, ich komme bald* und mein Lohn mit mir*, um einem jeden zu vergelten, wie sein Werk ist*.", footnotes: ["℘ Kap. 3,11; Joh 14,3", "℘ Jes 40,10; 62,11", "℘ Kap. 2,23; Ri 1,7; Hi 34,11; Hes 33,20"] },
      { number: 13, text: "Ich bin das Alpha und das Omega*, der Erste und der Letzte*, der Anfang und das Ende*.", footnotes: ["Alpha und Omega (A und O) sind der erste und der letzte Buchstabe des griech. Alphabets.\n℘ Kap. 1,8", "℘ Kap. 1,17", "o. Ziel"] },
      { number: 14, text: "Glückselig, die ihre Kleider waschen*, damit sie ein Anrecht* am Baum des Lebens* haben und durch die Tore in die Stadt hineingehen*!", footnotes: ["℘ Kap. 1,5", "o. eine Vollmacht", "℘ Kap. 2,7", "℘ Kap. 21,27"] },
      { number: 15, text: "Draußen* sind die Hunde* und die Zauberer und die Unzüchtigen* und die Mörder und die Götzendiener und jeder, der die Lüge liebt und tut*.", footnotes: ["℘ Mk 4,11", "℘ Phil 3,2", "o. Hurer", "℘ Kap. 21,8; Gal 5,21"] },
      { number: 16, text: "Ich, Jesus, habe meinen Engel gesandt*, euch diese Dinge für die Gemeinden* zu bezeugen*. Ich bin die Wurzel und das Geschlecht Davids*, der glänzende Morgenstern*.", footnotes: ["℘ Kap. 1,1", "o. Versammlungen", "℘ Kap. 1,1.11", "℘ Kap. 5,5; Mt 22,42-45", "℘ Kap. 2,28"] },
      { number: 17, text: "Und der Geist und die Braut* sagen: Komm! Und wer es hört, spreche: Komm! Und wen dürstet, der komme! Wer da will, nehme das Wasser des Lebens umsonst*!", footnotes: ["℘ Kap. 21,9", "℘ Kap. 21,6; Joh 7,37"] },
      { number: 18, text: "Ich bezeuge jedem, der die Worte der Weissagung dieses Buches hört: Wenn jemand <etwas> zu diesen Dingen hinzufügt*, so wird Gott ihm die Plagen hinzufügen, die in diesem Buch geschrieben sind;", footnotes: ["℘ Spr 30,6"] },
      { number: 19, text: "und wenn jemand <etwas> von den Worten des Buches dieser Weissagung wegnimmt*, so wird Gott seinen Teil* wegnehmen von dem Baum* des Lebens* und aus der heiligen Stadt, von denen in diesem Buch geschrieben ist*.", footnotes: ["℘ 5Mo 4,2", "o. seinen Anteil", "w. Holz", "℘ V. 2", "℘ Kap. 21,2.10"] },
      { number: 20, text: "Der diese Dinge bezeugt, spricht: Ja, ich komme bald*. Amen*; komm, Herr Jesus!", footnotes: ["℘ Kap. 3,11; Joh 14,3", "Beteuerungsformel für die Wahrhaftigkeit des Gesagten; in den Evangelien am Anfang feierlicher Erklärungen Jesu mit »Wahrlich!« übersetzt."] },
      { number: 21, text: "Die Gnade des Herrn Jesus sei mit allen*!", footnotes: ["Andere Handschr. lesen: mit den Heiligen, o. mit allen Heiligen\n℘ Röm 16,20"] },
    ]},
  ]
};
